insert into public.topics (id, curriculum_id, subject, grade, area, title, description, keywords, review_status, position) values
  ('prozentrechnung', 'nrw-gym-g9-mathe', 'Mathematik', 7, 'Zahlen und Größen', 'Prozentrechnung', 'Grundwert, Prozentwert und Prozentsatz verstehen und berechnen – mit Rabatten und Alltagsbeispielen.', array['prozentrechnung', 'prozent', 'prozente', 'prozentsatz', 'prozentwert', 'grundwert', 'rabatt', 'preisnachlass', 'mehrwertsteuer', 'anteil', '%']::text[], 'internal-review', 0),
  ('lineare-funktionen', 'nrw-gym-g9-mathe', 'Mathematik', 8, 'Funktionen', 'Lineare Funktionen', 'Funktionen verstehen, Steigung und y-Achsenabschnitt deuten, Geraden aufstellen und Sachaufgaben lösen.', array['lineare funktion', 'lineare funktionen', 'funktion', 'gerade', 'steigung', 'steigungsdreieck', 'y-achsenabschnitt', 'nullstelle', 'schnittpunkt', 'funktionsgleichung', 'wertetabelle', 'proportional', 'graph']::text[], 'internal-review', 1),
  ('lineare-gleichungssysteme', 'nrw-gym-g9-mathe', 'Mathematik', 8, 'Arithmetik/Algebra', 'Lineare Gleichungssysteme', 'Zwei Gleichungen mit zwei Variablen grafisch und rechnerisch lösen – mit Einsetzungs-, Gleichsetzungs- und Additionsverfahren.', array['lineare gleichungssysteme', 'gleichungssystem', 'gleichungssysteme', 'lgs', 'einsetzungsverfahren', 'gleichsetzungsverfahren', 'additionsverfahren', 'zwei variablen', 'zwei unbekannte', 'gleichungen mit zwei variablen']::text[], 'internal-review', 2),
  ('pythagoras', 'nrw-gym-g9-mathe', 'Mathematik', 9, 'Geometrie', 'Satz des Pythagoras', 'Seitenlängen in rechtwinkligen Dreiecken berechnen, prüfen und in Sachaufgaben anwenden.', array['satz des pythagoras', 'pythagoras', 'hypotenuse', 'kathete', 'katheten', 'rechtwinkliges dreieck', 'rechtwinklig', 'a2+b2=c2', 'a^2+b^2=c^2', 'diagonale', 'raumdiagonale']::text[], 'internal-review', 3),
  ('quadratische-gleichungen', 'nrw-gym-g9-mathe', 'Mathematik', 9, 'Algebra', 'Quadratische Gleichungen', 'Gleichungen mit $x^2$ lösen: Wurzelziehen, Satz vom Nullprodukt und pq-Formel.', array['quadratische gleichungen', 'quadratische gleichung', 'quadratisch', 'pq-formel', 'pq formel', 'pq', 'mitternachtsformel', 'abc-formel', 'diskriminante', 'nullprodukt', 'satz vom nullprodukt', 'x2', 'x^2']::text[], 'internal-review', 4),
  ('quadratische-funktionen', 'nrw-gym-g9-mathe', 'Mathematik', 9, 'Funktionen', 'Quadratische Funktionen', 'Parabeln verstehen: Streckung und Verschiebung, Scheitelpunkt, quadratische Ergänzung, Nullstellen und Anwendungen.', array['quadratische funktion', 'quadratische funktionen', 'parabel', 'normalparabel', 'scheitelpunkt', 'scheitel', 'scheitelpunktform', 'quadratische ergänzung', 'streckfaktor', 'gestreckt', 'gestaucht', 'verschiebung', 'nullstellen parabel', 'extremwert', 'flugbahn']::text[], 'internal-review', 5),
  ('kreis-zylinder', 'nrw-gym-g9-mathe', 'Mathematik', 9, 'Geometrie', 'Kreis und Zylinder', 'Umfang und Fläche von Kreisen, Kreisausschnitte und -ringe, Prismen und Zylinder berechnen.', array['kreis', 'kreise', 'kreisumfang', 'umfang', 'kreisfläche', 'flächeninhalt kreis', 'pi', 'π', 'kreiszahl', 'kreisausschnitt', 'kreisbogen', 'kreisring', 'zylinder', 'prisma', 'prismen', 'volumen', 'oberfläche', 'körper', 'körperberechnung']::text[], 'internal-review', 6)
insert into public.subtopics (id, topic_id, position, title, description, objective, intro, rules, example, summary) values
  ('prozent-grundbegriffe', 'prozentrechnung', 1, 'Grundbegriffe', 'Was bedeuten Grundwert, Prozentwert und Prozentsatz?', 'Du unterscheidest Grundwert, Prozentwert und Prozentsatz und wandelst Prozentangaben in Dezimalzahlen um.', '„Prozent“ heißt „von Hundert“. Mit Prozenten kann man Anteile gut vergleichen – egal wie groß das Ganze ist.', '[{"term":"Prozent","explanation":"$p\\,\\%$ bedeutet $p$ Hundertstel:","math":"p\\,\\% = \\frac{p}{100}"},{"term":"Grundwert $G$","explanation":"Das Ganze, auf das man sich bezieht (100 %)."},{"term":"Prozentwert $W$","explanation":"Der Anteil vom Ganzen."},{"term":"Prozentsatz $p\\,\\%$","explanation":"Der Anteil in Prozent."},{"term":"Grundgleichung","explanation":"","math":"W = G \\cdot \\frac{p}{100}"}]'::jsonb, '{"problem":"Wie viel sind $25\\,\\%$ von $80$ €?","steps":[{"text":"Grundwert $G = 80$, Prozentsatz $25\\,\\% = 0{,}25$."},{"text":"Rechnen:","math":"W = 80 \\cdot 0{,}25 = 20"}],"result":"$25\\,\\%$ von $80$ € sind $20$ €."}'::jsonb, '["$1\\,\\% = \\frac{1}{100} = 0{,}01$","Grundwert = Ganzes, Prozentwert = Teil, Prozentsatz = Anteil in %."]'::jsonb),
  ('prozent-prozentwert', 'prozentrechnung', 2, 'Prozentwert berechnen', 'Wie viel sind p % von einem Betrag?', 'Du berechnest den Prozentwert aus Grundwert und Prozentsatz, auch bei Rabatten.', 'Beim Einkaufen, bei Umfragen oder Noten: Oft willst du wissen, wie viel ein bestimmter Prozentsatz von einem Ganzen ist.', '[{"term":"Prozentwert","explanation":"","math":"W = G \\cdot \\frac{p}{100}"},{"term":"Dreisatz","explanation":"Alternativ: erst $1\\,\\%$ berechnen, dann mit $p$ malnehmen."}]'::jsonb, '{"problem":"Wie viel sind $15\\,\\%$ von $240$ €?","steps":[{"text":"$1\\,\\%$:","math":"240 : 100 = 2{,}4"},{"text":"$15\\,\\%$:","math":"2{,}4 \\cdot 15 = 36"}],"result":"$36$ €"}'::jsonb, '["$W = G \\cdot \\frac{p}{100}$","Dreisatz: über $1\\,\\%$ rechnen."]'::jsonb),
  ('prozent-satz-grundwert', 'prozentrechnung', 3, 'Prozentsatz und Grundwert berechnen', 'Rückwärts rechnen: Wie viel Prozent? Wie groß war das Ganze?', 'Du berechnest Prozentsatz und Grundwert und löst Aufgaben mit Rabatten rückwärts.', 'Manchmal kennst du den Teil und das Ganze und suchst den Anteil – oder du kennst den Teil und den Anteil und suchst das Ganze.', '[{"term":"Prozentsatz","explanation":"","math":"p\\,\\% = \\frac{W}{G}"},{"term":"Grundwert","explanation":"","math":"G = \\frac{W}{p\\,\\%}"},{"term":"Verminderter Grundwert","explanation":"Nach $p\\,\\%$ Rabatt bleiben $(100 - p)\\,\\%$ übrig."}]'::jsonb, '{"problem":"Du hast $18$ von $24$ Punkten. Wie viel Prozent sind das?","steps":[{"text":"Anteil berechnen:","math":"\\frac{18}{24} = 0{,}75 = 75\\,\\%"}],"result":"$75\\,\\%$"}'::jsonb, '["$p\\,\\% = W : G$","$G = W : p\\,\\%$","Rabatt rückwärts: durch den verbleibenden Anteil teilen."]'::jsonb),
  ('lf-funktionsbegriff', 'lineare-funktionen', 1, 'Funktionen und ihre Darstellung', 'Was ist eine Funktion? Wertetabelle, Graph, Funktionsgleichung und Funktionswerte.', 'Du erkennst Funktionen, liest und berechnest Funktionswerte und wechselst zwischen Tabelle, Gleichung und Graph.', 'Eine Funktion ordnet jedem Eingabewert $x$ **genau einen** Ausgabewert $y$ zu – wie ein Automat: Du wirfst $x$ ein, heraus kommt immer dasselbe $y$. Funktionen kann man als Wertetabelle, als Graph oder als Gleichung darstellen.', '[{"term":"Funktion","explanation":"Eine Zuordnung, die jedem $x$ aus der Definitionsmenge genau ein $y$ zuordnet."},{"term":"Funktionsgleichung","explanation":"Beschreibt die Zuordnung als Rechenvorschrift, z. B.","math":"f(x) = 2x + 1"},{"term":"Funktionswert","explanation":"$f(3)$ ist der $y$-Wert, der zu $x = 3$ gehört: $3$ einsetzen und ausrechnen."},{"term":"Definitionsmenge $D$","explanation":"Alle $x$-Werte, die man einsetzen darf."},{"term":"Graph","explanation":"Alle Punkte $(x\\,|\\,f(x))$ im Koordinatensystem."}]'::jsonb, '{"problem":"Berechne $f(4)$ für $f(x) = 3x - 5$.","steps":[{"text":"Setze $4$ für $x$ ein:","math":"f(4) = 3 \\cdot 4 - 5 = 12 - 5 = 7"}],"result":"$f(4) = 7$, also liegt der Punkt $(4\\,|\\,7)$ auf dem Graphen."}'::jsonb, '["Funktion: jedem $x$ genau ein $y$.","Funktionswert $f(a)$: $a$ einsetzen und ausrechnen.","Verschiedene $x$ dürfen dasselbe $y$ haben – ein $x$ aber nie zwei verschiedene $y$."]'::jsonb),
  ('lf-proportional', 'lineare-funktionen', 2, 'Proportionale Funktionen', 'Funktionen der Form $f(x) = mx$: Ursprungsgeraden, Quotientengleichheit, Preis pro Stück.', 'Du erkennst proportionale Zusammenhänge, bestimmst den Faktor $m$ und rechnest damit.', 'Bei einer proportionalen Funktion gehört zum doppelten $x$ das doppelte $y$, zum dreifachen $x$ das dreifache $y$. Der Quotient $\frac{y}{x}$ ist immer gleich – das ist die Steigung $m$. Der Graph ist eine Gerade durch den Ursprung.', '[{"term":"Proportionale Funktion","explanation":"Funktionsgleichung der Form","math":"f(x) = m \\cdot x"},{"term":"Steigung $m$","explanation":"Quotient aus $y$ und $x$ für jeden Punkt außer dem Ursprung:","math":"m = \\frac{y}{x}"},{"term":"Graph","explanation":"Eine Gerade durch den Ursprung $(0\\,|\\,0)$."},{"term":"Quotientengleichheit","explanation":"In einer Wertetabelle ist $\\frac{y}{x}$ bei allen Paaren gleich."}]'::jsonb, '{"problem":"Die Ursprungsgerade geht durch $P(4\\,|\\,6)$. Bestimme ihre Gleichung.","steps":[{"text":"Steigung als Quotient:","math":"m = \\frac{6}{4} = 1{,}5"},{"text":"Gleichung:","math":"f(x) = 1{,}5x"}],"result":"$f(x) = 1{,}5x$"}'::jsonb, '["$f(x) = mx$ – Graph ist eine Ursprungsgerade.","$m = \\frac{y}{x}$ für jeden Punkt auf der Geraden.","Doppeltes $x$ ⇒ doppeltes $y$."]'::jsonb),
  ('lf-steigung', 'lineare-funktionen', 3, 'Steigung und y-Achsenabschnitt', 'Was $m$ und $b$ in $f(x) = mx + b$ bedeuten: Steigungsdreieck, Steigung aus zwei Punkten, Steigung in Prozent.', 'Du liest Steigung und $y$-Achsenabschnitt ab, berechnest die Steigung aus zwei Punkten und deutest sie.', 'Der Graph von $f(x) = mx + b$ ist eine Gerade. $b$ verrät, wo sie die $y$-Achse schneidet. $m$ verrät, wie steil sie ist: Gehst du $1$ nach rechts, geht es $m$ nach oben (oder bei negativem $m$ nach unten).', '[{"term":"Lineare Funktion","explanation":"","math":"f(x) = mx + b"},{"term":"$y$-Achsenabschnitt $b$","explanation":"Die Gerade schneidet die $y$-Achse im Punkt $(0\\,|\\,b)$."},{"term":"Steigung $m$","explanation":"$m > 0$: steigend, $m < 0$: fallend, $m = 0$: waagerecht."},{"term":"Steigung aus zwei Punkten","explanation":"","math":"m = \\frac{y_2 - y_1}{x_2 - x_1}"},{"term":"Steigung in Prozent","explanation":"$m = 0{,}08$ entspricht $8\\,\\%$: $8$ m Höhe auf $100$ m waagerechte Strecke."}]'::jsonb, '{"problem":"Bestimme die Steigung der Geraden durch $A(1\\,|\\,2)$ und $B(4\\,|\\,8)$.","steps":[{"text":"Differenzen bilden:","math":"m = \\frac{8 - 2}{4 - 1} = \\frac{6}{3} = 2"}],"result":"Die Steigung ist $m = 2$: pro Schritt nach rechts geht es $2$ nach oben."}'::jsonb, '["$b$: Schnittpunkt mit der $y$-Achse $(0\\,|\\,b)$.","$m = \\frac{y_2 - y_1}{x_2 - x_1}$","Gleiche Steigung ⇒ parallele Geraden."]'::jsonb),
  ('lf-aufstellen', 'lineare-funktionen', 4, 'Funktionsgleichungen aufstellen', 'Gleichung einer Geraden aus Steigung und Punkt, aus zwei Punkten oder aus einem Graphen bestimmen.', 'Du stellst die Gleichung einer Geraden auf – aus Steigung und Punkt, aus zwei Punkten und aus Sachsituationen.', 'Durch zwei verschiedene Punkte geht genau eine Gerade. Um ihre Gleichung $y = mx + b$ zu finden, bestimmst du zuerst die Steigung $m$ und setzt dann einen Punkt ein, um $b$ zu berechnen.', '[{"term":"Aus Steigung und Punkt","explanation":"Punkt $P(x_P\\,|\\,y_P)$ einsetzen und nach $b$ auflösen:","math":"b = y_P - m \\cdot x_P"},{"term":"Aus zwei Punkten","explanation":"Erst die Steigung, dann wie oben $b$:","math":"m = \\frac{y_2 - y_1}{x_2 - x_1}"},{"term":"Probe","explanation":"Setze den zweiten Punkt ein – die Gleichung muss stimmen."}]'::jsonb, '{"problem":"Bestimme die Gleichung der Geraden durch $A(1\\,|\\,3)$ und $B(3\\,|\\,7)$.","steps":[{"text":"Steigung:","math":"m = \\frac{7 - 3}{3 - 1} = \\frac{4}{2} = 2"},{"text":"$A$ einsetzen:","math":"3 = 2 \\cdot 1 + b \\;\\Rightarrow\\; b = 1"},{"text":"Probe mit $B$:","math":"2 \\cdot 3 + 1 = 7 \\;\\checkmark"}],"result":"$y = 2x + 1$"}'::jsonb, '["Erst $m$, dann $b$ durch Einsetzen eines Punktes.","$b = y_P - m \\cdot x_P$","Mit dem zweiten Punkt die Probe machen."]'::jsonb),
  ('lf-nullstellen', 'lineare-funktionen', 5, 'Nullstellen und Schnittpunkte', 'Wo schneidet eine Gerade die Achsen? Wo schneiden sich zwei Geraden?', 'Du berechnest Nullstellen, Achsenschnittpunkte und den Schnittpunkt zweier Geraden.', 'Die Nullstelle ist die Stelle, an der der Graph die $x$-Achse schneidet – dort ist $f(x) = 0$. Zwei Geraden schneiden sich dort, wo beide denselben $y$-Wert haben: Man setzt die Funktionsterme gleich.', '[{"term":"Nullstelle","explanation":"Löse $f(x) = 0$. Für $f(x) = mx + b$ mit $m \\neq 0$:","math":"x_0 = -\\frac{b}{m}"},{"term":"Schnittpunkt mit der $y$-Achse","explanation":"$S_y(0\\,|\\,b)$"},{"term":"Schnittpunkt zweier Geraden","explanation":"Terme gleichsetzen, nach $x$ auflösen, $x$ in eine Gleichung einsetzen:","math":"m_1 x + b_1 = m_2 x + b_2"},{"term":"Parallele Geraden","explanation":"Gleiche Steigung, verschiedenes $b$ ⇒ kein Schnittpunkt."}]'::jsonb, '{"problem":"Bestimme den Schnittpunkt von $f(x) = 2x - 1$ und $g(x) = -x + 5$.","steps":[{"text":"Gleichsetzen:","math":"2x - 1 = -x + 5"},{"text":"Auflösen:","math":"3x = 6 \\;\\Rightarrow\\; x = 2"},{"text":"Einsetzen:","math":"f(2) = 2 \\cdot 2 - 1 = 3"}],"result":"Der Schnittpunkt ist $S(2\\,|\\,3)$."}'::jsonb, '["Nullstelle: $f(x) = 0$ lösen.","Schnittpunkt mit der $y$-Achse: $(0\\,|\\,b)$.","Schnittpunkt zweier Geraden: gleichsetzen, $x$ berechnen, $y$ durch Einsetzen."]'::jsonb),
  ('lf-anwendungen', 'lineare-funktionen', 6, 'Anwendungen', 'Tarife, Füllvorgänge und Bewegungen mit linearen Funktionen beschreiben, vergleichen und deuten.', 'Du beschreibst Sachsituationen mit linearen Funktionen, deutest $m$ und $b$ im Sachzusammenhang und vergleichst Angebote.', 'Viele Situationen im Alltag sind linear: ein fester Betrag plus ein gleichbleibender Betrag pro Einheit, ein gleichmäßig gefüllter Behälter, eine Fahrt mit konstanter Geschwindigkeit. Dann ist $b$ der Startwert und $m$ die Änderung pro Einheit.', '[{"term":"Startwert $b$","explanation":"Wert zu Beginn bzw. bei $x = 0$: Grundgebühr, Anfangsfüllung, Startposition."},{"term":"Änderungsrate $m$","explanation":"Änderung pro Einheit: Preis pro Kilometer, Liter pro Minute, Kilometer pro Stunde."},{"term":"Angebote vergleichen","explanation":"Funktionen gleichsetzen: Am Schnittpunkt sind beide gleich teuer; davor und danach ist jeweils ein anderes günstiger."},{"term":"Modellgrenzen","explanation":"Ein lineares Modell gilt nur in einem sinnvollen Bereich, z. B. nicht für negative Zeiten oder einen überlaufenden Tank."}]'::jsonb, '{"problem":"Anbieter A: $5$ € Grundgebühr, $0{,}50$ € pro km. Anbieter B: keine Grundgebühr, $0{,}75$ € pro km. Ab wie vielen Kilometern ist A günstiger?","steps":[{"text":"Funktionen:","math":"A(x) = 0{,}5x + 5,\\quad B(x) = 0{,}75x"},{"text":"Gleichsetzen:","math":"0{,}5x + 5 = 0{,}75x \\;\\Rightarrow\\; x = 20"},{"text":"Für $x > 20$ wächst B schneller, also ist dann A günstiger."}],"result":"Ab $20$ km ist Anbieter A günstiger."}'::jsonb, '["$b$ = Startwert, $m$ = Änderung pro Einheit.","Angebote vergleichen: gleichsetzen, Schnittpunkt deuten.","Auf den sinnvollen Bereich des Modells achten."]'::jsonb),
  ('lgs-gleichungen', 'lineare-gleichungssysteme', 1, 'Gleichungen mit zwei Variablen', 'Lösungspaare finden und prüfen, Gleichungen nach $y$ umstellen, Sachsituationen beschreiben.', 'Du prüfst und bestimmst Lösungspaare einer linearen Gleichung mit zwei Variablen und stellst sie nach $y$ um.', 'Eine Gleichung wie $2x + y = 10$ hat nicht nur eine Lösung, sondern unendlich viele Zahlenpaare $(x\,|\,y)$: $(0\,|\,10)$, $(1\,|\,8)$, $(5\,|\,0)$ … Stellt man sie nach $y$ um, erhält man $y = -2x + 10$ – eine Gerade. Alle Lösungspaare liegen auf dieser Geraden.', '[{"term":"Lineare Gleichung mit zwei Variablen","explanation":"","math":"ax + by = c"},{"term":"Lösungspaar","explanation":"Ein Paar $(x\\,|\\,y)$, das beim Einsetzen eine wahre Aussage ergibt."},{"term":"Nach $y$ umstellen","explanation":"Für $b \\neq 0$:","math":"y = -\\frac{a}{b}x + \\frac{c}{b}"},{"term":"Graph","explanation":"Alle Lösungspaare bilden eine Gerade."}]'::jsonb, '{"problem":"Ist $(3\\,|\\,4)$ eine Lösung von $2x + 3y = 18$? Stelle die Gleichung nach $y$ um.","steps":[{"text":"Einsetzen:","math":"2 \\cdot 3 + 3 \\cdot 4 = 6 + 12 = 18 \\;\\checkmark"},{"text":"Nach $y$ umstellen:","math":"3y = -2x + 18 \\;\\Rightarrow\\; y = -\\frac{2}{3}x + 6"}],"result":"$(3\\,|\\,4)$ ist eine Lösung; die Gerade ist $y = -\\frac{2}{3}x + 6$."}'::jsonb, '["Eine lineare Gleichung mit zwei Variablen hat unendlich viele Lösungspaare.","Prüfen: einsetzen und vergleichen.","Umgestellt nach $y$ beschreibt sie eine Gerade."]'::jsonb),
  ('lgs-grafisch', 'lineare-gleichungssysteme', 2, 'Grafisches Lösen', 'Beide Gleichungen als Geraden zeichnen und den Schnittpunkt ablesen – und erkennen, wann es keine oder unendlich viele Lösungen gibt.', 'Du löst Gleichungssysteme zeichnerisch und erkennst an der Lage der Geraden die Anzahl der Lösungen.', 'Jede der beiden Gleichungen beschreibt eine Gerade. Ein Zahlenpaar, das **beide** Gleichungen erfüllt, liegt auf beiden Geraden – also im Schnittpunkt. Dazu stellt man beide Gleichungen nach $y$ um, zeichnet die Geraden und liest den Schnittpunkt ab.', '[{"term":"Lösung eines LGS","explanation":"Der Schnittpunkt der beiden Geraden."},{"term":"Vorgehen","explanation":"Beide Gleichungen nach $y$ umstellen, Geraden zeichnen, Schnittpunkt ablesen, Probe machen."},{"term":"Anzahl der Lösungen","explanation":"Geraden schneiden sich: genau eine · parallel: keine · identisch: unendlich viele."},{"term":"Grenzen","explanation":"Ablesen ist ungenau, wenn der Schnittpunkt nicht auf Gitterpunkten liegt – dann rechnerisch lösen."}]'::jsonb, '{"problem":"Löse grafisch: $\\text{I: } y = x + 1$, $\\text{II: } y = -x + 3$.","steps":[{"text":"Beide Geraden zeichnen: I schneidet die $y$-Achse bei $1$ (Steigung $1$), II bei $3$ (Steigung $-1$)."},{"text":"Schnittpunkt ablesen: $S(1\\,|\\,2)$."},{"text":"Probe:","math":"\\text{I: } 1 + 1 = 2 \\;\\checkmark \\quad \\text{II: } -1 + 3 = 2 \\;\\checkmark"}],"result":"Lösung: $(1\\,|\\,2)$"}'::jsonb, '["Lösung = Schnittpunkt der Geraden.","Parallel ⇒ keine Lösung, identisch ⇒ unendlich viele.","Immer eine Probe machen."]'::jsonb),
  ('lgs-einsetzen', 'lineare-gleichungssysteme', 3, 'Einsetzungsverfahren', 'Eine Gleichung nach einer Variablen auflösen und den Term in die andere Gleichung einsetzen.', 'Du löst lineare Gleichungssysteme rechnerisch mit dem Einsetzungsverfahren.', 'Ist eine Gleichung schon nach einer Variablen aufgelöst, z. B. $y = 2x + 1$, kannst du den Term $2x + 1$ für $y$ in die andere Gleichung einsetzen. Übrig bleibt eine Gleichung mit nur noch einer Variablen.', '[{"term":"Schritt 1","explanation":"Eine Gleichung nach $x$ oder $y$ auflösen (am besten die, wo das ohne Brüche geht)."},{"term":"Schritt 2","explanation":"Den Term in die andere Gleichung einsetzen – mit Klammern!"},{"term":"Schritt 3","explanation":"Die entstandene Gleichung lösen."},{"term":"Schritt 4","explanation":"Das Ergebnis einsetzen, um die zweite Variable zu berechnen; Probe machen."}]'::jsonb, '{"problem":"Löse $\\text{I: } y = 2x - 1$ und $\\text{II: } 3x + y = 9$.","steps":[{"text":"I in II einsetzen:","math":"3x + (2x - 1) = 9"},{"text":"Lösen:","math":"5x - 1 = 9 \\;\\Rightarrow\\; x = 2"},{"text":"In I einsetzen:","math":"y = 2 \\cdot 2 - 1 = 3"}],"result":"Lösung: $(2\\,|\\,3)$"}'::jsonb, '["Auflösen – einsetzen (mit Klammer) – lösen – zurückeinsetzen.","Günstig, wenn eine Variable schon allein steht oder den Faktor $1$ hat.","Probe in beiden Gleichungen."]'::jsonb),
  ('lgs-gleichsetzen', 'lineare-gleichungssysteme', 4, 'Gleichsetzungsverfahren', 'Beide Gleichungen nach derselben Variablen auflösen und die Terme gleichsetzen.', 'Du löst lineare Gleichungssysteme rechnerisch mit dem Gleichsetzungsverfahren.', 'Sind beide Gleichungen nach derselben Variablen aufgelöst, etwa $y = 2x + 1$ und $y = -x + 7$, müssen die rechten Seiten gleich sein – sonst wäre $y$ nicht derselbe Wert. Man setzt die Terme gleich und erhält eine Gleichung mit nur einer Variablen.', '[{"term":"Schritt 1","explanation":"Beide Gleichungen nach derselben Variablen auflösen."},{"term":"Schritt 2","explanation":"Die beiden Terme gleichsetzen."},{"term":"Schritt 3","explanation":"Die Gleichung lösen."},{"term":"Schritt 4","explanation":"Das Ergebnis in eine der Gleichungen einsetzen; Probe machen."}]'::jsonb, '{"problem":"Löse $\\text{I: } y = 2x + 1$ und $\\text{II: } y = -x + 7$.","steps":[{"text":"Gleichsetzen:","math":"2x + 1 = -x + 7"},{"text":"Lösen:","math":"3x = 6 \\;\\Rightarrow\\; x = 2"},{"text":"Einsetzen:","math":"y = 2 \\cdot 2 + 1 = 5"}],"result":"Lösung: $(2\\,|\\,5)$"}'::jsonb, '["Beide nach derselben Variablen auflösen, dann gleichsetzen.","Besonders günstig, wenn beide schon in der Form $y = \\ldots$ vorliegen.","Das entspricht dem Schnittpunkt zweier Geraden."]'::jsonb),
  ('lgs-addition', 'lineare-gleichungssysteme', 5, 'Additionsverfahren', 'Gleichungen so vervielfachen und addieren, dass eine Variable wegfällt.', 'Du löst lineare Gleichungssysteme rechnerisch mit dem Additionsverfahren.', 'Addiert man zwei Gleichungen, bleibt die Gleichheit erhalten. Stehen vor $y$ Gegenzahlen wie $+3y$ und $-3y$, fällt $y$ beim Addieren weg. Ist das nicht so, multipliziert man vorher eine oder beide Gleichungen mit passenden Zahlen.', '[{"term":"Schritt 1","explanation":"Gleichungen so multiplizieren, dass vor einer Variablen Gegenzahlen (oder gleiche Zahlen) stehen."},{"term":"Schritt 2","explanation":"Gleichungen addieren (bei Gegenzahlen) bzw. subtrahieren (bei gleichen Zahlen) – die Variable fällt weg."},{"term":"Schritt 3","explanation":"Die entstandene Gleichung lösen."},{"term":"Schritt 4","explanation":"Ergebnis in eine Ausgangsgleichung einsetzen; Probe machen."}]'::jsonb, '{"problem":"Löse $\\text{I: } 2x + 3y = 12$ und $\\text{II: } 4x - 3y = 6$.","steps":[{"text":"I + II: $y$ fällt weg.","math":"6x = 18 \\;\\Rightarrow\\; x = 3"},{"text":"In I einsetzen:","math":"6 + 3y = 12 \\;\\Rightarrow\\; y = 2"}],"result":"Lösung: $(3\\,|\\,2)$"}'::jsonb, '["Ziel: Gegenzahlen vor einer Variablen.","Gleichungen addieren – eine Variable fällt weg.","Ganze Gleichung multiplizieren (beide Seiten, alle Summanden!)."]'::jsonb),
  ('lgs-sonderfaelle', 'lineare-gleichungssysteme', 6, 'Sonderfälle', 'Gleichungssysteme ohne Lösung oder mit unendlich vielen Lösungen erkennen und deuten.', 'Du erkennst rechnerisch und am Gleichungssystem, ob es keine, genau eine oder unendlich viele Lösungen gibt.', 'Nicht jedes Gleichungssystem hat genau eine Lösung. Fallen beim Rechnen **beide** Variablen weg, bleibt eine Aussage ohne Variable übrig: Ist sie falsch (z. B. $0 = 5$), gibt es keine Lösung – die Geraden sind parallel. Ist sie wahr ($0 = 0$), gibt es unendlich viele Lösungen – die Geraden sind identisch.', '[{"term":"Falsche Aussage","explanation":"z. B. $0 = 5$ ⇒ keine Lösung, $L = \\{\\}$ (parallele Geraden)."},{"term":"Wahre Aussage","explanation":"$0 = 0$ ⇒ unendlich viele Lösungen (identische Geraden)."},{"term":"Ohne Rechnen erkennen","explanation":"Ist die linke Seite von II ein Vielfaches der linken Seite von I, gibt es keine oder unendlich viele Lösungen – je nachdem, ob die rechte Seite im selben Verhältnis steht."}]'::jsonb, '{"problem":"Löse $\\text{I: } x + 2y = 4$, $\\text{II: } 2x + 4y = 10$.","steps":[{"text":"II − 2 · I:","math":"0x + 0y = 2"},{"text":"$0 = 2$ ist eine falsche Aussage."}],"result":"Das Gleichungssystem hat keine Lösung ($L = \\{\\}$); die Geraden sind parallel."}'::jsonb, '["$0 = $ Zahl $\\neq 0$ ⇒ keine Lösung.","$0 = 0$ ⇒ unendlich viele Lösungen.","Linke Seiten Vielfache voneinander ⇒ Sonderfall prüfen."]'::jsonb),
  ('lgs-sachaufgaben', 'lineare-gleichungssysteme', 7, 'Sachaufgaben', 'Textaufgaben mit zwei Unbekannten: Variablen festlegen, Gleichungssystem aufstellen, lösen und die Antwort prüfen.', 'Du übersetzt Sachsituationen in lineare Gleichungssysteme, löst sie und prüfst das Ergebnis am Text.', 'Viele Rätsel und Alltagsfragen haben zwei Unbekannte, zum Beispiel zwei Preise oder zwei Anzahlen. Mit zwei Informationen lassen sich zwei Gleichungen aufstellen. So gehst du vor: Variablen festlegen – Gleichungen aufstellen – lösen – Antwort formulieren – am Text prüfen.', '[{"term":"1. Variablen festlegen","explanation":"Schreibe auf, wofür $x$ und $y$ stehen (mit Einheit)."},{"term":"2. Gleichungen aufstellen","explanation":"Jede Information des Textes ergibt eine Gleichung."},{"term":"3. Lösen","explanation":"Mit einem passenden Verfahren (Einsetzen, Gleichsetzen, Addition)."},{"term":"4. Prüfen","explanation":"Passt das Ergebnis zum Text? Sind Anzahlen ganzzahlig und nicht negativ?"}]'::jsonb, '{"problem":"Im Kino zahlen 2 Erwachsene und 3 Kinder 36 €, 1 Erwachsener und 2 Kinder 21 €. Was kosten die Karten?","steps":[{"text":"$x$ = Preis Erwachsene, $y$ = Preis Kinder (in €):","math":"\\text{I: } 2x + 3y = 36, \\quad \\text{II: } x + 2y = 21"},{"text":"I − 2 · II:","math":"-y = -6 \\;\\Rightarrow\\; y = 6"},{"text":"In II:","math":"x + 12 = 21 \\;\\Rightarrow\\; x = 9"},{"text":"Probe in I: $18 + 18 = 36$ ✓"}],"result":"Erwachsene zahlen $9$ €, Kinder $6$ €."}'::jsonb, '["Variablen mit Bedeutung festlegen.","Zwei Informationen ⇒ zwei Gleichungen.","Ergebnis am Text prüfen."]'::jsonb),
  ('pyth-grundlagen', 'pythagoras', 1, 'Grundlagen und Definition', 'Katheten, Hypotenuse und die Aussage des Satzes kennenlernen.', 'Du kennst den Satz des Pythagoras und kannst ihn für ein rechtwinkliges Dreieck mit den richtigen Seitenbezeichnungen aufschreiben.', 'In einem rechtwinkligen Dreieck hängen die drei Seitenlängen auf besondere Weise zusammen. Wenn du zwei Seiten kennst, kannst du die dritte berechnen. Dafür musst du zuerst wissen, welche Seite welche Rolle spielt.', '[{"term":"Rechtwinkliges Dreieck","explanation":"Ein Dreieck mit einem Winkel von genau $90^\\circ$."},{"term":"Katheten","explanation":"Die beiden Seiten, die den rechten Winkel einschließen."},{"term":"Hypotenuse","explanation":"Die Seite gegenüber dem rechten Winkel. Sie ist immer die längste Seite."},{"term":"Satz des Pythagoras","explanation":"Sind $a$ und $b$ die Katheten und $c$ die Hypotenuse, dann gilt:","math":"a^2 + b^2 = c^2"}]'::jsonb, '{"problem":"Ein rechtwinkliges Dreieck hat die Katheten $a = 3$ und $b = 4$. Prüfe, dass $c = 5$ die Hypotenuse sein kann.","steps":[{"text":"Der rechte Winkel liegt zwischen $a$ und $b$, also ist $c$ die Hypotenuse."},{"text":"Quadrate der Katheten addieren:","math":"3^2 + 4^2 = 9 + 16 = 25"},{"text":"Quadrat der Hypotenuse:","math":"5^2 = 25"},{"text":"Beide Seiten sind gleich, der Satz ist erfüllt."}],"result":"$3^2 + 4^2 = 5^2$, also passt $c = 5$."}'::jsonb, '["Katheten bilden den rechten Winkel, die Hypotenuse liegt ihm gegenüber.","Die Hypotenuse ist die längste Seite.","Es gilt $a^2 + b^2 = c^2$, wenn $c$ die Hypotenuse ist."]'::jsonb),
  ('pyth-erkennen', 'pythagoras', 2, 'Rechtwinklige Dreiecke erkennen', 'Rechte Winkel finden – auch in gedrehten oder anders beschrifteten Dreiecken.', 'Du erkennst rechtwinklige Dreiecke über die Winkel und benennst Katheten und Hypotenuse auch in gedrehten Figuren.', 'Bevor du den Satz des Pythagoras anwendest, musst du sicher sein, dass ein rechter Winkel vorhanden ist und wo er liegt. Die Lage oder Drehung des Dreiecks spielt dabei keine Rolle.', '[{"term":"Winkelsumme","explanation":"In jedem Dreieck ergeben die drei Innenwinkel zusammen $180^\\circ$.","math":"\\alpha + \\beta + \\gamma = 180^\\circ"},{"term":"Dritter Winkel","explanation":"Kennst du zwei Winkel, erhältst du den dritten durch $180^\\circ$ minus deren Summe."},{"term":"Lage egal","explanation":"Ein Dreieck bleibt rechtwinklig, egal wie es gedreht ist. Die Hypotenuse liegt immer dem rechten Winkel gegenüber."}]'::jsonb, '{"problem":"In einem Dreieck $ABC$ gilt $\\alpha = 35^\\circ$ und $\\beta = 55^\\circ$. Ist es rechtwinklig?","steps":[{"text":"Dritten Winkel berechnen:","math":"\\gamma = 180^\\circ - 35^\\circ - 55^\\circ = 90^\\circ"},{"text":"Der rechte Winkel liegt bei $C$, also ist $c$ die Hypotenuse."}],"result":"Ja, das Dreieck ist rechtwinklig mit rechtem Winkel bei $C$."}'::jsonb, '["Die Winkelsumme im Dreieck beträgt $180^\\circ$.","Die Hypotenuse liegt immer gegenüber dem rechten Winkel – unabhängig von der Lage."]'::jsonb),
  ('pyth-herleitung', 'pythagoras', 3, 'Herleitung des Satzes', 'Warum der Satz gilt: Flächen von Quadraten und der Ergänzungsbeweis.', 'Du kannst den Satz des Pythagoras mit Quadratflächen deuten und den Ergänzungsbeweis nachvollziehen.', 'Der Satz des Pythagoras ist eigentlich eine Aussage über Flächen: Zeichnet man über jede Seite ein Quadrat, dann sind die beiden kleinen Quadrate zusammen genauso groß wie das große Quadrat.', '[{"term":"Quadratfläche","explanation":"Ein Quadrat mit Seitenlänge $s$ hat den Flächeninhalt","math":"A = s^2"},{"term":"Flächenaussage","explanation":"Die Kathetenquadrate haben zusammen denselben Flächeninhalt wie das Hypotenusenquadrat."},{"term":"Ergänzungsbeweis","explanation":"Ein Quadrat mit Seite $a+b$ enthält vier gleiche rechtwinklige Dreiecke und ein inneres Quadrat mit Seite $c$:","math":"(a+b)^2 = 4 \\cdot \\tfrac{a \\cdot b}{2} + c^2 \\;\\Rightarrow\\; a^2 + b^2 = c^2"}]'::jsonb, '{"problem":"Katheten $a = 3$, $b = 4$. Vergleiche die Quadratflächen.","steps":[{"text":"Quadrat über $a$:","math":"3^2 = 9"},{"text":"Quadrat über $b$:","math":"4^2 = 16"},{"text":"Zusammen:","math":"9 + 16 = 25 = 5^2"}],"result":"Das Quadrat über der Hypotenuse $c = 5$ hat genau $25$ Flächeneinheiten."}'::jsonb, '["$a^2$, $b^2$, $c^2$ sind Flächeninhalte von Quadraten über den Seiten.","Der Ergänzungsbeweis zeigt die Gleichung durch Zerlegen eines großen Quadrats."]'::jsonb),
  ('pyth-hypotenuse', 'pythagoras', 4, 'Hypotenuse berechnen', 'Aus zwei Katheten die längste Seite bestimmen.', 'Du berechnest die Hypotenuse aus zwei gegebenen Katheten und rundest sinnvoll.', 'Kennst du beide Katheten, kannst du die Hypotenuse in drei Schritten berechnen: quadrieren, addieren, Wurzel ziehen.', '[{"term":"Formel","explanation":"Für die Hypotenuse gilt:","math":"c = \\sqrt{a^2 + b^2}"},{"term":"Reihenfolge","explanation":"Erst quadrieren, dann addieren, zum Schluss die Wurzel ziehen."},{"term":"Achtung","explanation":"Die Wurzel einer Summe ist nicht die Summe der Wurzeln:","math":"\\sqrt{a^2 + b^2} \\neq a + b"}]'::jsonb, '{"problem":"Berechne $c$ für $a = 5$ cm und $b = 12$ cm.","steps":[{"text":"Quadrieren:","math":"5^2 = 25,\\quad 12^2 = 144"},{"text":"Addieren:","math":"c^2 = 25 + 144 = 169"},{"text":"Wurzel ziehen:","math":"c = \\sqrt{169} = 13"}],"result":"$c = 13$ cm"}'::jsonb, '["$c = \\sqrt{a^2 + b^2}$","Ergebnis plausibel? Die Hypotenuse muss länger als jede Kathete sein."]'::jsonb),
  ('pyth-kathete', 'pythagoras', 5, 'Kathete berechnen', 'Eine fehlende Kathete aus Hypotenuse und anderer Kathete bestimmen.', 'Du stellst den Satz nach einer Kathete um und berechnest sie.', 'Ist die Hypotenuse bekannt, wird nicht addiert, sondern subtrahiert. Wichtig: Die Hypotenuse steht immer allein.', '[{"term":"Umgestellt nach $a$","explanation":"","math":"a = \\sqrt{c^2 - b^2}"},{"term":"Umgestellt nach $b$","explanation":"","math":"b = \\sqrt{c^2 - a^2}"},{"term":"Kontrolle","explanation":"Die Kathete muss kürzer als die Hypotenuse sein."}]'::jsonb, '{"problem":"Gegeben: $c = 10$ cm, $a = 6$ cm. Berechne $b$.","steps":[{"text":"Umstellen:","math":"b^2 = c^2 - a^2"},{"text":"Einsetzen:","math":"b^2 = 100 - 36 = 64"},{"text":"Wurzel:","math":"b = 8"}],"result":"$b = 8$ cm"}'::jsonb, '["Kathete: $\\sqrt{c^2 - \\text{andere Kathete}^2}$","Die Kathete ist immer kürzer als die Hypotenuse."]'::jsonb),
  ('pyth-umkehrung', 'pythagoras', 6, 'Umkehrung des Satzes', 'Mit drei Seitenlängen prüfen, ob ein Dreieck rechtwinklig ist.', 'Du prüfst mit der Umkehrung des Satzes, ob ein Dreieck mit gegebenen Seiten rechtwinklig ist.', 'Der Satz funktioniert auch rückwärts: Erfüllen die Seiten die Gleichung, dann muss das Dreieck einen rechten Winkel haben.', '[{"term":"Umkehrung","explanation":"Gilt für die längste Seite $c$ die Gleichung $a^2 + b^2 = c^2$, dann ist das Dreieck rechtwinklig. Der rechte Winkel liegt gegenüber von $c$."},{"term":"Längste Seite","explanation":"Setze immer die längste Seite als $c$ ein."},{"term":"Pythagoreische Tripel","explanation":"Ganzzahlige Lösungen, z. B. $(3, 4, 5)$, $(5, 12, 13)$, $(8, 15, 17)$."}]'::jsonb, '{"problem":"Ist ein Dreieck mit den Seiten $7$, $24$ und $25$ rechtwinklig?","steps":[{"text":"Längste Seite: $c = 25$."},{"text":"Prüfen:","math":"7^2 + 24^2 = 49 + 576 = 625"},{"text":"Vergleich:","math":"25^2 = 625"}],"result":"Ja, das Dreieck ist rechtwinklig."}'::jsonb, '["Längste Seite als $c$ wählen.","$a^2 + b^2 = c^2$ ⇒ rechtwinklig; sonst nicht."]'::jsonb),
  ('pyth-anwendung', 'pythagoras', 7, 'Anwendungs- und Textaufgaben', 'Leitern, Bildschirme, Drachen: den Satz im Alltag anwenden.', 'Du findest in Sachsituationen rechtwinklige Dreiecke und löst die Aufgabe mit einem Antwortsatz.', 'Viele Alltagsfragen verstecken ein rechtwinkliges Dreieck. Eine Skizze hilft dir, es zu finden.', '[{"term":"Schritt 1","explanation":"Skizze zeichnen und das rechtwinklige Dreieck markieren."},{"term":"Schritt 2","explanation":"Gegebene und gesuchte Seiten eintragen. Ist die gesuchte Seite Hypotenuse oder Kathete?"},{"term":"Schritt 3","explanation":"Rechnen, Einheit beachten, Antwortsatz schreiben."}]'::jsonb, '{"problem":"Eine $5$ m lange Leiter steht $1{,}4$ m von einer Wand entfernt. Wie hoch reicht sie?","steps":[{"text":"Leiter = Hypotenuse $c = 5$, Abstand zur Wand = Kathete $a = 1{,}4$."},{"text":"Höhe gesucht (Kathete):","math":"h = \\sqrt{5^2 - 1{,}4^2} = \\sqrt{25 - 1{,}96} = \\sqrt{23{,}04}"},{"text":"Ergebnis:","math":"h = 4{,}8"}],"result":"Die Leiter reicht $4{,}8$ m hoch."}'::jsonb, '["Erst skizzieren, dann rechnen.","Prüfe, ob die gesuchte Seite Hypotenuse oder Kathete ist.","Antwortsatz mit Einheit."]'::jsonb),
  ('pyth-gemischt', 'pythagoras', 8, 'Gemischte Übungen und Prüfungsvorbereitung', 'Alle Aufgabentypen gemischt – wie in der Klassenarbeit.', 'Du wählst selbstständig den passenden Ansatz und löst auch mehrschrittige Aufgaben.', 'Hier kommt alles zusammen. Überlege bei jeder Aufgabe zuerst: Wo ist das rechtwinklige Dreieck, und was ist gesucht?', '[{"term":"Quadratdiagonale","explanation":"Für ein Quadrat mit Seite $s$ gilt:","math":"d = s\\sqrt{2}"},{"term":"Höhe im gleichseitigen Dreieck","explanation":"Für die Seitenlänge $s$ gilt:","math":"h = \\sqrt{s^2 - \\left(\\tfrac{s}{2}\\right)^2}"},{"term":"Raumdiagonale","explanation":"Im Quader mit Kanten $a$, $b$, $c$:","math":"d = \\sqrt{a^2 + b^2 + c^2}"}]'::jsonb, '{"problem":"Wie lang ist die Raumdiagonale eines Würfels mit Kantenlänge $2$ cm?","steps":[{"text":"Flächendiagonale:","math":"e = \\sqrt{2^2 + 2^2} = \\sqrt{8}"},{"text":"Raumdiagonale:","math":"d = \\sqrt{e^2 + 2^2} = \\sqrt{8 + 4} = \\sqrt{12} \\approx 3{,}46"}],"result":"$d \\approx 3{,}46$ cm"}'::jsonb, '["Rechtwinklige Dreiecke auch in Quadraten, Rechtecken und Körpern suchen.","Mehrschrittige Aufgaben in Teilschritte zerlegen."]'::jsonb),
  ('quad-reinquadratisch', 'quadratische-gleichungen', 1, 'Reinquadratische Gleichungen', 'Gleichungen der Form $x^2 = d$ durch Wurzelziehen lösen.', 'Du löst Gleichungen der Form $x^2 = d$ und gibst alle Lösungen an.', 'Wenn in einer Gleichung nur $x^2$ und Zahlen vorkommen, kannst du nach $x^2$ auflösen und dann die Wurzel ziehen – aber Vorsicht: Es gibt oft zwei Lösungen.', '[{"term":"Zwei Lösungen","explanation":"Für $d > 0$:","math":"x^2 = d \\;\\Rightarrow\\; x = \\sqrt{d} \\text{ oder } x = -\\sqrt{d}"},{"term":"Eine Lösung","explanation":"Für $d = 0$ ist $x = 0$."},{"term":"Keine Lösung","explanation":"Für $d < 0$ gibt es keine reelle Lösung."}]'::jsonb, '{"problem":"Löse $2x^2 - 18 = 0$.","steps":[{"text":"$+18$:","math":"2x^2 = 18"},{"text":"$:2$:","math":"x^2 = 9"},{"text":"Wurzel ziehen:","math":"x_1 = 3,\\; x_2 = -3"}],"result":"$L = \\{-3;\\, 3\\}$"}'::jsonb, '["Nach $x^2$ auflösen, dann $\\pm$ Wurzel.","Negative rechte Seite ⇒ keine Lösung."]'::jsonb),
  ('quad-nullprodukt', 'quadratische-gleichungen', 2, 'Satz vom Nullprodukt', 'Gleichungen durch Ausklammern und Faktorisieren lösen.', 'Du löst quadratische Gleichungen mit dem Satz vom Nullprodukt, auch nach dem Ausklammern.', 'Ein Produkt ist genau dann null, wenn mindestens ein Faktor null ist. Dieser einfache Gedanke hilft beim Lösen vieler Gleichungen.', '[{"term":"Satz vom Nullprodukt","explanation":"","math":"a \\cdot b = 0 \\;\\Leftrightarrow\\; a = 0 \\text{ oder } b = 0"},{"term":"Ausklammern","explanation":"Fehlt das Absolutglied, klammere $x$ aus:","math":"x^2 + px = x(x + p) = 0"},{"term":"Achtung","explanation":"Nie durch $x$ teilen – dabei geht die Lösung $x = 0$ verloren."}]'::jsonb, '{"problem":"Löse $x^2 - 5x = 0$.","steps":[{"text":"Ausklammern:","math":"x(x - 5) = 0"},{"text":"Nullprodukt:","math":"x = 0 \\text{ oder } x - 5 = 0"}],"result":"$L = \\{0;\\, 5\\}$"}'::jsonb, '["Produkt $= 0$ ⇒ ein Faktor $= 0$.","Ausklammern statt durch $x$ teilen."]'::jsonb),
  ('quad-pq-formel', 'quadratische-gleichungen', 3, 'pq-Formel', 'Allgemeine quadratische Gleichungen in Normalform lösen.', 'Du bringst Gleichungen in Normalform, wendest die pq-Formel an und bestimmst die Anzahl der Lösungen mit der Diskriminante.', 'Mit der pq-Formel lässt sich jede quadratische Gleichung in Normalform lösen. Die Diskriminante verrät vorher, wie viele Lösungen es gibt.', '[{"term":"Normalform","explanation":"","math":"x^2 + px + q = 0"},{"term":"pq-Formel","explanation":"","math":"x_{1,2} = -\\frac{p}{2} \\pm \\sqrt{\\left(\\frac{p}{2}\\right)^2 - q}"},{"term":"Diskriminante","explanation":"$D = \\left(\\frac{p}{2}\\right)^2 - q$: $D > 0$ zwei, $D = 0$ eine, $D < 0$ keine Lösung."},{"term":"Vorher","explanation":"Steht vor $x^2$ eine Zahl $a \\neq 1$, teile zuerst die ganze Gleichung durch $a$."}]'::jsonb, '{"problem":"Löse $x^2 - 6x + 8 = 0$.","steps":[{"text":"Ablesen: $p = -6$, $q = 8$."},{"text":"Einsetzen:","math":"x_{1,2} = 3 \\pm \\sqrt{9 - 8} = 3 \\pm 1"},{"text":"Lösungen:","math":"x_1 = 4,\\; x_2 = 2"}],"result":"$L = \\{2;\\, 4\\}$"}'::jsonb, '["Normalform herstellen.","$p$ und $q$ mit Vorzeichen ablesen.","Diskriminante entscheidet über die Anzahl der Lösungen."]'::jsonb),
  ('qf-normalparabel', 'quadratische-funktionen', 1, 'Normalparabel und Streckung', 'Der Graph von $f(x) = x^2$ und was der Faktor $a$ in $f(x) = ax^2$ bewirkt.', 'Du kennst die Normalparabel, deutest den Faktor $a$ und berechnest Werte von $f(x) = ax^2$.', 'Quadriert man jede Zahl, entsteht die Normalparabel $f(x) = x^2$: ein U-förmiger Graph mit dem tiefsten Punkt im Ursprung, symmetrisch zur $y$-Achse. Ein Faktor $a$ davor streckt, staucht oder spiegelt die Parabel. So beschreibt man zum Beispiel Bremswege oder den freien Fall.', '[{"term":"Normalparabel","explanation":"Scheitelpunkt $S(0\\,|\\,0)$, symmetrisch zur $y$-Achse:","math":"f(x) = x^2"},{"term":"Faktor $a$","explanation":"$a > 0$: nach oben geöffnet, $a < 0$: nach unten geöffnet. $|a| > 1$: gestreckt (schmaler), $|a| < 1$: gestaucht (breiter).","math":"f(x) = a \\cdot x^2"},{"term":"Faktor aus einem Punkt","explanation":"Liegt $P(x_P\\,|\\,y_P)$ auf der Parabel, gilt:","math":"a = \\frac{y_P}{x_P^2}"},{"term":"Symmetrie","explanation":"$f(-x) = f(x)$: Zu $x$ und $-x$ gehört derselbe Funktionswert."}]'::jsonb, '{"problem":"Die Parabel $f(x) = a x^2$ geht durch $P(2\\,|\\,-6)$. Bestimme $a$ und beschreibe die Parabel.","steps":[{"text":"Punkt einsetzen:","math":"-6 = a \\cdot 2^2 = 4a"},{"text":"Nach $a$ auflösen:","math":"a = \\frac{-6}{4} = -1{,}5"},{"text":"$a < 0$ und $|a| > 1$: nach unten geöffnet und gestreckt."}],"result":"$f(x) = -1{,}5x^2$, nach unten geöffnet und schmaler als die Normalparabel."}'::jsonb, '["Normalparabel: $f(x) = x^2$, Scheitel $(0\\,|\\,0)$.","Vorzeichen von $a$: Öffnung nach oben oder unten.","$|a| > 1$ gestreckt, $|a| < 1$ gestaucht.","$a = \\frac{y}{x^2}$ aus einem Punkt."]'::jsonb),
  ('qf-scheitelform', 'quadratische-funktionen', 2, 'Scheitelpunktform', 'Parabeln verschieben und den Scheitelpunkt aus $f(x) = a(x - d)^2 + e$ ablesen.', 'Du liest den Scheitelpunkt aus der Scheitelpunktform ab, beschreibst Verschiebungen und stellst Gleichungen auf.', 'Verschiebt man eine Parabel, wandert ihr Scheitelpunkt mit. In der Scheitelpunktform $f(x) = a(x - d)^2 + e$ steht er direkt drin: $S(d\,|\,e)$. Achtung beim Vorzeichen in der Klammer – $(x - 2)^2$ verschiebt nach rechts, $(x + 2)^2$ nach links. Mit der Scheitelpunktform beschreibt man zum Beispiel Flugbahnen und Brückenbögen.', '[{"term":"Scheitelpunktform","explanation":"Scheitelpunkt $S(d\\,|\\,e)$, Streckfaktor $a$:","math":"f(x) = a(x - d)^2 + e"},{"term":"Verschiebung","explanation":"$d > 0$: nach rechts, $d < 0$: nach links; $e > 0$: nach oben, $e < 0$: nach unten."},{"term":"Vorzeichen in der Klammer","explanation":"$(x + 3)^2 = (x - (-3))^2$, also $d = -3$.","math":"(x + 3)^2 \\;\\Rightarrow\\; d = -3"},{"term":"Kleinster bzw. größter Wert","explanation":"$a > 0$: kleinster Funktionswert $e$; $a < 0$: größter Funktionswert $e$."}]'::jsonb, '{"problem":"Gib den Scheitelpunkt von $f(x) = -2(x + 1)^2 + 4$ an und beschreibe die Parabel.","steps":[{"text":"Klammer umschreiben:","math":"(x + 1)^2 = (x - (-1))^2 \\;\\Rightarrow\\; d = -1"},{"text":"Der Summand hinten ist $e = 4$.","math":"S(-1\\,|\\,4)"},{"text":"$a = -2$: nach unten geöffnet und gestreckt. Der größte Funktionswert ist $4$."}],"result":"$S(-1\\,|\\,4)$, nach unten geöffnet, gestreckt."}'::jsonb, '["$f(x) = a(x - d)^2 + e$ hat den Scheitelpunkt $S(d\\,|\\,e)$.","Vorzeichen in der Klammer umdrehen: $(x + 3)^2 \\Rightarrow d = -3$.","$e$ verschiebt nach oben bzw. unten."]'::jsonb),
  ('qf-allgemeine-form', 'quadratische-funktionen', 3, 'Allgemeine Form und Scheitelpunkt', 'Von $f(x) = x^2 + px + q$ zur Scheitelpunktform – mit der quadratischen Ergänzung.', 'Du formst zwischen allgemeiner Form und Scheitelpunktform um und bestimmst so den Scheitelpunkt.', 'Oft ist eine Parabel in der allgemeinen Form $f(x) = ax^2 + bx + c$ gegeben. Den Schnittpunkt mit der $y$-Achse liest man sofort ab: $(0\,|\,c)$. Für den Scheitelpunkt formt man mit der quadratischen Ergänzung in die Scheitelpunktform um – oder nutzt die Formel $x_S = -\frac{p}{2}$. Damit lassen sich zum Beispiel größte Gewinne oder größte Flächen berechnen.', '[{"term":"Allgemeine Form","explanation":"Schnittpunkt mit der $y$-Achse: $(0\\,|\\,c)$.","math":"f(x) = ax^2 + bx + c"},{"term":"Scheitelpunkt bei $a = 1$","explanation":"Für $f(x) = x^2 + px + q$:","math":"S\\left(-\\frac{p}{2}\\,\\middle|\\,q - \\left(\\frac{p}{2}\\right)^2\\right)"},{"term":"Quadratische Ergänzung","explanation":"$\\left(\\frac{p}{2}\\right)^2$ addieren und abziehen, dann binomische Formel:","math":"x^2 + px + q = \\left(x + \\frac{p}{2}\\right)^2 + q - \\left(\\frac{p}{2}\\right)^2"},{"term":"Scheitelpunkt allgemein","explanation":"Für $f(x) = ax^2 + bx + c$:","math":"x_S = -\\frac{b}{2a},\\quad y_S = f(x_S)"}]'::jsonb, '{"problem":"Bestimme den Scheitelpunkt von $f(x) = x^2 - 6x + 5$.","steps":[{"text":"$p = -6$, also $\\frac{p}{2} = -3$ und $\\left(\\frac{p}{2}\\right)^2 = 9$."},{"text":"Ergänzen:","math":"x^2 - 6x + 9 - 9 + 5 = (x - 3)^2 - 4"},{"text":"Ablesen:","math":"S(3\\,|\\,-4)"}],"result":"Der Scheitelpunkt ist $S(3\\,|\\,-4)$."}'::jsonb, '["$y$-Achsenabschnitt der allgemeinen Form: $c$.","$x_S = -\\frac{p}{2}$ bzw. $x_S = -\\frac{b}{2a}$.","Quadratische Ergänzung führt zur Scheitelpunktform."]'::jsonb),
  ('qf-nullstellen', 'quadratische-funktionen', 4, 'Nullstellen und Anwendungen', 'Wo schneidet eine Parabel die $x$-Achse – und wo eine Gerade?', 'Du berechnest Nullstellen und Schnittpunkte quadratischer Funktionen und nutzt sie in Sachaufgaben.', 'Die Nullstellen einer quadratischen Funktion sind die Lösungen der Gleichung $f(x) = 0$ – hier hilft dein Wissen über quadratische Gleichungen, vor allem die pq-Formel. Eine Parabel hat keine, eine oder zwei Nullstellen. Um Schnittpunkte mit einer Geraden zu finden, setzt man die Funktionsterme gleich. So lässt sich etwa berechnen, wann ein geworfener Ball landet.', '[{"term":"Nullstellen","explanation":"Löse $f(x) = 0$. Für $x^2 + px + q = 0$:","math":"x_{1,2} = -\\frac{p}{2} \\pm \\sqrt{\\left(\\frac{p}{2}\\right)^2 - q}"},{"term":"Anzahl der Nullstellen","explanation":"Diskriminante $D = \\left(\\frac{p}{2}\\right)^2 - q$: $D > 0$ zwei, $D = 0$ eine, $D < 0$ keine."},{"term":"Linearfaktorform","explanation":"Nullstellen direkt ablesen:","math":"f(x) = a(x - x_1)(x - x_2)"},{"term":"Schnittpunkt mit einer Geraden","explanation":"Terme gleichsetzen, auf eine Seite bringen und die quadratische Gleichung lösen."}]'::jsonb, '{"problem":"Berechne die Nullstellen von $f(x) = 2x^2 - 4x - 6$.","steps":[{"text":"Null setzen und durch $2$ teilen:","math":"x^2 - 2x - 3 = 0"},{"text":"pq-Formel mit $p = -2$, $q = -3$:","math":"x_{1,2} = 1 \\pm \\sqrt{1 + 3} = 1 \\pm 2"},{"text":"Lösungen:","math":"x_1 = -1,\\; x_2 = 3"}],"result":"Die Nullstellen sind $x_1 = -1$ und $x_2 = 3$."}'::jsonb, '["Nullstellen: $f(x) = 0$ lösen, bei $a \\neq 1$ erst durch $a$ teilen.","Diskriminante entscheidet über die Anzahl.","Schnittpunkt Parabel–Gerade: gleichsetzen."]'::jsonb),
  ('kz-umfang', 'kreis-zylinder', 1, 'Kreisumfang und die Zahl π', 'Umfang aus Radius oder Durchmesser berechnen – und umgekehrt.', 'Du berechnest den Umfang eines Kreises und bestimmst Radius oder Durchmesser aus dem Umfang.', 'Bei jedem Kreis ist der Umfang etwas mehr als dreimal so lang wie der Durchmesser. Das Verhältnis $\frac{u}{d}$ ist immer gleich – die Kreiszahl $\pi \approx 3{,}14159$. Daraus folgt die Umfangsformel.', '[{"term":"Kreiszahl $\\pi$","explanation":"Verhältnis von Umfang zu Durchmesser, $\\pi \\approx 3{,}14$. Rechne mit der $\\pi$-Taste."},{"term":"Umfang","explanation":"","math":"u = \\pi \\cdot d = 2 \\pi r"},{"term":"Radius aus dem Umfang","explanation":"","math":"r = \\frac{u}{2\\pi}"},{"term":"Durchmesser","explanation":"$d = 2r$"}]'::jsonb, '{"problem":"Ein Kreis hat den Radius $r = 4$ cm. Berechne den Umfang.","steps":[{"text":"Formel anwenden:","math":"u = 2 \\pi \\cdot 4\\,\\text{cm} = 8\\pi\\,\\text{cm} \\approx 25{,}1\\,\\text{cm}"}],"result":"$u \\approx 25{,}1$ cm"}'::jsonb, '["$u = \\pi d = 2\\pi r$","$\\pi \\approx 3{,}14$ – mit der $\\pi$-Taste rechnen.","$r = \\frac{u}{2\\pi}$"]'::jsonb),
  ('kz-flaeche', 'kreis-zylinder', 2, 'Flächeninhalt des Kreises', 'Kreisfläche aus Radius oder Durchmesser berechnen, Radius aus der Fläche bestimmen.', 'Du berechnest den Flächeninhalt eines Kreises und bestimmst den Radius aus dem Flächeninhalt.', 'Zerschneidet man einen Kreis in viele schmale Tortenstücke und legt sie abwechselnd nebeneinander, entsteht fast ein Rechteck: so breit wie der halbe Umfang ($\pi r$) und so hoch wie der Radius ($r$). Sein Flächeninhalt ist $\pi r \cdot r = \pi r^2$.', '[{"term":"Flächeninhalt","explanation":"","math":"A = \\pi r^2"},{"term":"Mit dem Durchmesser","explanation":"Erst $r = \\frac{d}{2}$ berechnen, dann einsetzen."},{"term":"Radius aus der Fläche","explanation":"","math":"r = \\sqrt{\\frac{A}{\\pi}}"},{"term":"Achtung","explanation":"Verdoppelt man den Radius, vervierfacht sich die Fläche."}]'::jsonb, '{"problem":"Berechne den Flächeninhalt eines Kreises mit $d = 10$ cm.","steps":[{"text":"Radius:","math":"r = \\frac{10}{2} = 5\\,\\text{cm}"},{"text":"Fläche:","math":"A = \\pi \\cdot 5^2 = 25\\pi \\approx 78{,}5\\,\\text{cm}^2"}],"result":"$A \\approx 78{,}5$ cm²"}'::jsonb, '["$A = \\pi r^2$","Bei gegebenem Durchmesser erst halbieren.","$r = \\sqrt{A : \\pi}$"]'::jsonb),
  ('kz-ausschnitt', 'kreis-zylinder', 3, 'Kreisbogen und Kreisausschnitt', 'Teile eines Kreises berechnen: Bogenlänge und Fläche eines „Tortenstücks“ mit dem Mittelpunktswinkel α.', 'Du berechnest Bogenlänge und Flächeninhalt von Kreisausschnitten und bestimmst den Mittelpunktswinkel.', 'Ein Kreisausschnitt ist wie ein Tortenstück. Sein Mittelpunktswinkel $\alpha$ verrät, welcher Anteil des ganzen Kreises es ist: $\frac{\alpha}{360^\circ}$. Genau dieser Anteil vom Umfang ist die Bogenlänge, und dieser Anteil von der Kreisfläche ist die Fläche des Ausschnitts.', '[{"term":"Anteil am Kreis","explanation":"","math":"\\frac{\\alpha}{360^\\circ}"},{"term":"Bogenlänge","explanation":"","math":"b = \\frac{\\alpha}{360^\\circ} \\cdot 2\\pi r"},{"term":"Fläche des Kreisausschnitts","explanation":"","math":"A_S = \\frac{\\alpha}{360^\\circ} \\cdot \\pi r^2"},{"term":"Winkel aus der Bogenlänge","explanation":"","math":"\\alpha = \\frac{b}{2\\pi r} \\cdot 360^\\circ"}]'::jsonb, '{"problem":"Berechne Bogenlänge und Fläche eines Kreisausschnitts mit $r = 6$ cm und $\\alpha = 60^\\circ$.","steps":[{"text":"Anteil:","math":"\\frac{60^\\circ}{360^\\circ} = \\frac{1}{6}"},{"text":"Bogen:","math":"b = \\frac{1}{6} \\cdot 2\\pi \\cdot 6 = 2\\pi \\approx 6{,}3\\,\\text{cm}"},{"text":"Fläche:","math":"A_S = \\frac{1}{6} \\cdot \\pi \\cdot 36 = 6\\pi \\approx 18{,}8\\,\\text{cm}^2"}],"result":"$b \\approx 6{,}3$ cm, $A_S \\approx 18{,}8$ cm²"}'::jsonb, '["Anteil $\\frac{\\alpha}{360^\\circ}$ vom ganzen Kreis.","$b = \\frac{\\alpha}{360^\\circ} \\cdot 2\\pi r$","$A_S = \\frac{\\alpha}{360^\\circ} \\cdot \\pi r^2$"]'::jsonb),
  ('kz-ring', 'kreis-zylinder', 4, 'Kreisring', 'Fläche zwischen zwei Kreisen mit gemeinsamem Mittelpunkt berechnen.', 'Du berechnest den Flächeninhalt von Kreisringen und bestimmst fehlende Radien.', 'Ein Kreisring entsteht, wenn man aus einem großen Kreis einen kleineren Kreis mit demselben Mittelpunkt herausschneidet – wie bei einer Unterlegscheibe oder einem Donut. Seine Fläche ist die große Kreisfläche minus die kleine.', '[{"term":"Kreisring","explanation":"Außenradius $R$, Innenradius $r$:","math":"A = \\pi R^2 - \\pi r^2 = \\pi (R^2 - r^2)"},{"term":"Ringbreite","explanation":"$R - r$"},{"term":"Achtung","explanation":"Nicht $\\pi (R - r)^2$ rechnen – das ist falsch!"}]'::jsonb, '{"problem":"Eine Unterlegscheibe hat außen $R = 5$ mm und innen $r = 2$ mm. Wie groß ist ihre Fläche?","steps":[{"text":"Große minus kleine Kreisfläche:","math":"A = \\pi (5^2 - 2^2) = 21\\pi \\approx 66{,}0\\,\\text{mm}^2"}],"result":"$A \\approx 66{,}0$ mm²"}'::jsonb, '["$A = \\pi (R^2 - r^2)$","Erst quadrieren, dann subtrahieren.","Bei Durchmessern zuerst halbieren."]'::jsonb),
  ('kz-prisma', 'kreis-zylinder', 5, 'Prismen', 'Netz, Oberfläche und Volumen von Prismen mit dreieckiger, rechteckiger oder trapezförmiger Grundfläche.', 'Du berechnest Volumen und Oberfläche von Prismen und bestimmst fehlende Größen.', 'Ein Prisma hat zwei gleiche, parallele Grundflächen (z. B. Dreiecke) und rechteckige Seitenflächen. Stell dir vor, die Grundfläche wird gleichmäßig nach oben „geschoben“: Das Volumen ist dann Grundfläche mal Höhe. Die Oberfläche besteht aus den beiden Grundflächen und dem Mantel.', '[{"term":"Volumen","explanation":"","math":"V = G \\cdot h"},{"term":"Oberfläche","explanation":"Zwei Grundflächen plus Mantel:","math":"O = 2G + M"},{"term":"Mantel","explanation":"Umfang der Grundfläche mal Höhe:","math":"M = u_G \\cdot h"},{"term":"Einheiten","explanation":"$1\\,\\text{dm}^3 = 1$ Liter, $1\\,\\text{m}^3 = 1000$ Liter."}]'::jsonb, '{"problem":"Ein Prisma hat als Grundfläche ein rechtwinkliges Dreieck mit den Katheten $3$ cm und $4$ cm (Hypotenuse $5$ cm) und die Höhe $10$ cm.","steps":[{"text":"Grundfläche:","math":"G = \\frac{3 \\cdot 4}{2} = 6\\,\\text{cm}^2"},{"text":"Volumen:","math":"V = 6 \\cdot 10 = 60\\,\\text{cm}^3"},{"text":"Oberfläche:","math":"O = 2 \\cdot 6 + (3 + 4 + 5) \\cdot 10 = 132\\,\\text{cm}^2"}],"result":"$V = 60$ cm³, $O = 132$ cm²"}'::jsonb, '["$V = G \\cdot h$","$O = 2G + u_G \\cdot h$","Liter: $1$ dm³ $= 1$ ℓ"]'::jsonb),
  ('kz-zylinder', 'kreis-zylinder', 6, 'Zylinder', 'Volumen, Mantel und Oberfläche von Kreiszylindern – Dosen, Rohre, Säulen.', 'Du berechnest Volumen, Mantelfläche und Oberfläche von Zylindern und bestimmst fehlende Größen.', 'Ein Zylinder ist wie ein Prisma mit kreisförmiger Grundfläche: Volumen gleich Grundfläche mal Höhe. Rollt man den Mantel ab, entsteht ein Rechteck – so lang wie der Umfang des Kreises und so hoch wie der Zylinder.', '[{"term":"Volumen","explanation":"","math":"V = \\pi r^2 h"},{"term":"Mantelfläche","explanation":"Abgerollt ein Rechteck:","math":"M = 2\\pi r h"},{"term":"Oberfläche","explanation":"Zwei Kreise plus Mantel:","math":"O = 2\\pi r^2 + 2\\pi r h"},{"term":"Höhe aus dem Volumen","explanation":"","math":"h = \\frac{V}{\\pi r^2}"}]'::jsonb, '{"problem":"Eine Dose hat $r = 4$ cm und $h = 10$ cm. Berechne Volumen und Oberfläche.","steps":[{"text":"Volumen:","math":"V = \\pi \\cdot 4^2 \\cdot 10 = 160\\pi \\approx 502{,}7\\,\\text{cm}^3"},{"text":"Oberfläche:","math":"O = 2\\pi \\cdot 16 + 2\\pi \\cdot 4 \\cdot 10 = 112\\pi \\approx 351{,}9\\,\\text{cm}^2"}],"result":"$V \\approx 502{,}7$ cm³ (gut ein halber Liter), $O \\approx 351{,}9$ cm²"}'::jsonb, '["$V = \\pi r^2 h$","$M = 2\\pi r h$","$O = 2\\pi r^2 + 2\\pi r h$"]'::jsonb),
  ('kz-zusammengesetzt', 'kreis-zylinder', 7, 'Zusammengesetzte Körper', 'Rohre, Bohrungen und Bauwerke aus Quadern, Prismen und Zylindern berechnen.', 'Du zerlegst Körper in Prismen und Zylinder bzw. ergänzt sie und berechnest so ihr Volumen und ihre Masse.', 'Viele Gegenstände sind aus einfachen Körpern zusammengesetzt: ein Haus aus Quader und Prisma, ein Rohr aus zwei Zylindern, ein Werkstück mit einer Bohrung. Man berechnet die Teilkörper einzeln und addiert (zusammengesetzt) oder subtrahiert (ausgeschnitten) die Volumen.', '[{"term":"Zusammensetzen","explanation":"Volumen der Teilkörper addieren."},{"term":"Aushöhlen","explanation":"Volumen des herausgenommenen Teils abziehen, z. B. Rohr:","math":"V = \\pi (R^2 - r^2) h"},{"term":"Masse","explanation":"Volumen mal Dichte:","math":"m = V \\cdot \\rho"}]'::jsonb, '{"problem":"Ein Rohr ist $2$ m lang, außen $R = 5$ cm und innen $r = 4$ cm. Wie groß ist das Materialvolumen?","steps":[{"text":"Großer minus kleiner Zylinder (alles in cm):","math":"V = \\pi (5^2 - 4^2) \\cdot 200 = 1800\\pi \\approx 5655\\,\\text{cm}^3"}],"result":"$V \\approx 5655$ cm³ $\\approx 5{,}7$ Liter"}'::jsonb, '["Zerlegen oder ergänzen.","Teilvolumen addieren bzw. subtrahieren.","Einheiten vorher angleichen."]'::jsonb)
