  ('lgs-gs-sach-schwer-06', 'lgs-gleichsetzen', 69, 'equation', 'application', 3, null, null, 'Ein Rechteck hat den Umfang $32$ cm. Seine Länge ist $2$ cm größer als seine Breite. Wie lang ($x$) und wie breit ($y$) ist es (in cm)? Gib die Lösung als $(x\,|\,y)$ an.', null, '{"kind":"point"}'::jsonb, array['Gleichungssysteme mit dem Gleichsetzungsverfahren lösen', 'Sachaufgaben mit LGS']::text[], null),
  ('lgs-gs-sach-schwer-07', 'lgs-gleichsetzen', 70, 'equation', 'application', 3, null, null, 'Ein Rechteck hat den Umfang $46$ cm. Seine Länge ist $5$ cm größer als seine Breite. Wie lang ($x$) und wie breit ($y$) ist es (in cm)? Gib die Lösung als $(x\,|\,y)$ an.', null, '{"kind":"point"}'::jsonb, array['Gleichungssysteme mit dem Gleichsetzungsverfahren lösen', 'Sachaufgaben mit LGS']::text[], null),
  ('lgs-gs-sach-schwer-08', 'lgs-gleichsetzen', 71, 'equation', 'application', 3, null, null, 'Für ein Fest werden $8$ Liter Schorle aus Saft (Literpreis $1{,}5$ €) und Mineralwasser (Literpreis $0{,}5$ €) gemischt. Die Zutaten kosten zusammen $6$ €. Wie viele Liter Saft ($x$) und Wasser ($y$) werden verwendet? Gib die Lösung als $(x\,|\,y)$ an.', null, '{"kind":"point"}'::jsonb, array['Gleichungssysteme mit dem Gleichsetzungsverfahren lösen', 'Sachaufgaben mit LGS']::text[], null),
  ('lgs-gs-fc-1', 'lgs-gleichsetzen', 72, 'multiple-choice', 'knowledge', 1, null, 'formula', 'Welcher Ansatz gehört zum Gleichsetzungsverfahren für $\text{I: } y = m_1x + n_1$ und $\text{II: } y = m_2x + n_2$?', '[{"id":"a","label":"$m_1x + n_1 + m_2x + n_2 = 0$"},{"id":"b","label":"$m_1x + n_1 = 0$"},{"id":"c","label":"$m_1x + n_1 = m_2x + n_2$"},{"id":"d","label":"$m_1 = m_2$"}]'::jsonb, '{"kind":"choice"}'::jsonb, array['Formeln kennen']::text[], null),
  ('lgs-ad-1', 'lgs-addition', 0, 'multiple-choice', 'knowledge', 1, null, 'concept', 'Wann kann man zwei Gleichungen direkt addieren, sodass $y$ wegfällt?', '[{"id":"a","label":"Wenn vor $y$ Gegenzahlen stehen, z. B. $+2y$ und $-2y$"},{"id":"b","label":"Wenn vor $y$ dieselbe Zahl steht, z. B. $+2y$ und $+2y$"},{"id":"c","label":"Wenn beide rechten Seiten gleich sind"},{"id":"d","label":"Immer"}]'::jsonb, '{"kind":"choice"}'::jsonb, array['Gleichungssysteme mit dem Additionsverfahren lösen']::text[], null)
