  ('pyth-ka-rechnung-01', 'pyth-kathete', 54, 'multiple-choice', 'reasoning', 2, null, null, 'Ein rechtwinkliges Dreieck hat die Hypotenuse $50$ cm und eine Kathete $14$ cm. Welche Rechnung liefert die andere Kathete?', '[{"id":"a","label":"$\\sqrt{50^2 - 14^2}$"},{"id":"b","label":"$\\sqrt{50^2 + 14^2}$"},{"id":"c","label":"$\\sqrt{14^2 - 50^2}$"},{"id":"d","label":"$50 - 14$"}]'::jsonb, '{"kind":"choice"}'::jsonb, array['Satz des Pythagoras anwenden']::text[], null),
  ('pyth-ka-rechnung-02', 'pyth-kathete', 55, 'multiple-choice', 'reasoning', 2, null, null, 'Ein rechtwinkliges Dreieck hat die Hypotenuse $17$ cm und eine Kathete $8$ cm. Welche Rechnung liefert die andere Kathete?', '[{"id":"a","label":"$\\sqrt{8^2 - 17^2}$"},{"id":"b","label":"$\\sqrt{17^2 + 8^2}$"},{"id":"c","label":"$17 - 8$"},{"id":"d","label":"$\\sqrt{17^2 - 8^2}$"}]'::jsonb, '{"kind":"choice"}'::jsonb, array['Satz des Pythagoras anwenden']::text[], null),
  ('pyth-ka-rechnung-03', 'pyth-kathete', 56, 'multiple-choice', 'reasoning', 2, null, null, 'Ein rechtwinkliges Dreieck hat die Hypotenuse $25$ cm und eine Kathete $7$ cm. Welche Rechnung liefert die andere Kathete?', '[{"id":"a","label":"$\\sqrt{25^2 - 7^2}$"},{"id":"b","label":"$25 - 7$"},{"id":"c","label":"$\\sqrt{7^2 - 25^2}$"},{"id":"d","label":"$\\sqrt{25^2 + 7^2}$"}]'::jsonb, '{"kind":"choice"}'::jsonb, array['Satz des Pythagoras anwenden']::text[], null),
  ('pyth-ka-rechnung-04', 'pyth-kathete', 57, 'multiple-choice', 'reasoning', 2, null, null, 'Ein rechtwinkliges Dreieck hat die Hypotenuse $41$ cm und eine Kathete $9$ cm. Welche Rechnung liefert die andere Kathete?', '[{"id":"a","label":"$\\sqrt{41^2 - 9^2}$"},{"id":"b","label":"$41 - 9$"},{"id":"c","label":"$\\sqrt{41^2 + 9^2}$"},{"id":"d","label":"$\\sqrt{9^2 - 41^2}$"}]'::jsonb, '{"kind":"choice"}'::jsonb, array['Satz des Pythagoras anwenden']::text[], null),
  ('pyth-ka-rechnung-05', 'pyth-kathete', 58, 'multiple-choice', 'reasoning', 2, null, null, 'Ein rechtwinkliges Dreieck hat die Hypotenuse $20$ cm und eine Kathete $12$ cm. Welche Rechnung liefert die andere Kathete?', '[{"id":"a","label":"$\\sqrt{12^2 - 20^2}$"},{"id":"b","label":"$20 - 12$"},{"id":"c","label":"$\\sqrt{20^2 - 12^2}$"},{"id":"d","label":"$\\sqrt{20^2 + 12^2}$"}]'::jsonb, '{"kind":"choice"}'::jsonb, array['Satz des Pythagoras anwenden']::text[], null),
  ('pyth-ka-rechnung-06', 'pyth-kathete', 59, 'multiple-choice', 'reasoning', 2, null, null, 'Ein rechtwinkliges Dreieck hat die Hypotenuse $34$ cm und eine Kathete $16$ cm. Welche Rechnung liefert die andere Kathete?', '[{"id":"a","label":"$\\sqrt{34^2 + 16^2}$"},{"id":"b","label":"$\\sqrt{16^2 - 34^2}$"},{"id":"c","label":"$\\sqrt{34^2 - 16^2}$"},{"id":"d","label":"$34 - 16$"}]'::jsonb, '{"kind":"choice"}'::jsonb, array['Satz des Pythagoras anwenden']::text[], null),
  ('pyth-ka-rechnung-07', 'pyth-kathete', 60, 'multiple-choice', 'reasoning', 2, null, null, 'Ein rechtwinkliges Dreieck hat die Hypotenuse $13$ cm und eine Kathete $5$ cm. Welche Rechnung liefert die andere Kathete?', '[{"id":"a","label":"$13 - 5$"},{"id":"b","label":"$\\sqrt{5^2 - 13^2}$"},{"id":"c","label":"$\\sqrt{13^2 - 5^2}$"},{"id":"d","label":"$\\sqrt{13^2 + 5^2}$"}]'::jsonb, '{"kind":"choice"}'::jsonb, array['Satz des Pythagoras anwenden']::text[], null),
  ('pyth-ka-rechnung-08', 'pyth-kathete', 61, 'multiple-choice', 'reasoning', 2, null, null, 'Ein rechtwinkliges Dreieck hat die Hypotenuse $25$ cm und eine Kathete $15$ cm. Welche Rechnung liefert die andere Kathete?', '[{"id":"a","label":"$\\sqrt{25^2 + 15^2}$"},{"id":"b","label":"$\\sqrt{15^2 - 25^2}$"},{"id":"c","label":"$\\sqrt{25^2 - 15^2}$"},{"id":"d","label":"$25 - 15$"}]'::jsonb, '{"kind":"choice"}'::jsonb, array['Satz des Pythagoras anwenden']::text[], null),
  ('pyth-ka-fc-1', 'pyth-kathete', 62, 'text', 'knowledge', 2, null, 'formula', 'Gib die Formel für die Kathete $b$ an, wenn die Hypotenuse $c$ und die Kathete $a$ bekannt sind. (Wurzel z. B. als `√(...)`)', null, '{"kind":"text"}'::jsonb, array['Formeln kennen']::text[], null),
  ('pyth-ka-fc-2', 'pyth-kathete', 63, 'multiple-choice', 'knowledge', 1, null, 'concept', 'Warum wird für eine Kathete $c^2 - a^2$ gerechnet und nicht $a^2 - c^2$?', '[{"id":"a","label":"Weil die Hypotenuse $c$ die längste Seite ist – sonst käme unter der Wurzel etwas Negatives heraus."},{"id":"b","label":"Weil man immer die zweite von der ersten Zahl abzieht."},{"id":"c","label":"Das ist egal, beides ergibt dasselbe."},{"id":"d","label":"Weil $a$ immer die kürzeste Seite ist."}]'::jsonb, '{"kind":"choice"}'::jsonb, array['Formeln kennen']::text[], null),
  ('pyth-umkehrung-1', 'pyth-umkehrung', 0, 'multiple-choice', 'reasoning', 1, null, 'concept', 'Welche Seitenlängen ergeben ein rechtwinkliges Dreieck?', '[{"id":"a","label":"$4$, $5$, $6$"},{"id":"b","label":"$2$, $3$, $4$"},{"id":"c","label":"$6$, $8$, $10$"},{"id":"d","label":"$5$, $6$, $7$"}]'::jsonb, '{"kind":"choice"}'::jsonb, array['Umkehrung anwenden']::text[], null),
  ('pyth-umkehrung-2', 'pyth-umkehrung', 1, 'multiple-choice', 'reasoning', 2, null, null, 'Ein Dreieck hat die Seiten $5$ cm, $7$ cm und $9$ cm. Ist es rechtwinklig?', '[{"id":"a","label":"Ja, weil $5 + 7 > 9$."},{"id":"b","label":"Nein, weil $5^2 + 7^2 = 74 \\neq 81 = 9^2$."},{"id":"c","label":"Ja, weil $9$ die längste Seite ist."},{"id":"d","label":"Nein, weil $5 + 7 \\neq 9$."}]'::jsonb, '{"kind":"choice"}'::jsonb, array['Umkehrung anwenden', 'Begründen']::text[], null),
