  ('kz-fl-1', 'kz-flaeche', 0, 'multiple-choice', 'knowledge', 1, null, 'formula', 'Welche Formel gibt den Flächeninhalt eines Kreises an?', '[{"id":"a","label":"$A = \\pi r^2$"},{"id":"b","label":"$A = 2\\pi r$"},{"id":"c","label":"$A = \\pi d^2$"},{"id":"d","label":"$A = (\\pi r)^2$"}]'::jsonb, '{"kind":"choice"}'::jsonb, array['Flächeninhalt eines Kreises berechnen']::text[], null),
