  ('lgs-gs-sach-03', '[{"text":"Variablen: $x$ = Alter der Mutter, $y$ = Alter der Tochter. Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & x + y = 60 \\\\ \\text{II:}\\;\\; & x - y = 30 \\end{aligned}"},{"text":"Gleichungen addieren – $y$ fällt weg:","math":"2x = 90"},{"text":"Nach $x$ auflösen:","math":"x = 45"},{"text":"$x$ in Gleichung I einsetzen:","math":"45 + y = 60 \\;\\Rightarrow\\; y = 15"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 45$, $y = 15$', null, null),
  ('lgs-gs-sach-04', '[{"text":"Variablen: $x$ = größere Zahl, $y$ = kleinere Zahl. Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & x + y = 61 \\\\ \\text{II:}\\;\\; & x - y = 55 \\end{aligned}"},{"text":"Gleichungen addieren – $y$ fällt weg:","math":"2x = 116"},{"text":"Nach $x$ auflösen:","math":"x = 58"},{"text":"$x$ in Gleichung I einsetzen:","math":"58 + y = 61 \\;\\Rightarrow\\; y = 3"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 58$, $y = 3$', null, null),
