  ('lgs-gs-sach-06', '[{"text":"Variablen: $x$ = Alter der Mutter, $y$ = Alter der Tochter. Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & x + y = 55 \\\\ \\text{II:}\\;\\; & x - y = 33 \\end{aligned}"},{"text":"Gleichungen addieren – $y$ fällt weg:","math":"2x = 88"},{"text":"Nach $x$ auflösen:","math":"x = 44"},{"text":"$x$ in Gleichung I einsetzen:","math":"44 + y = 55 \\;\\Rightarrow\\; y = 11"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 44$, $y = 11$', null, null),
  ('lgs-gs-sach-07', '[{"text":"Variablen: $x$ = größere Zahl, $y$ = kleinere Zahl. Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & x + y = 54 \\\\ \\text{II:}\\;\\; & x - y = 46 \\end{aligned}"},{"text":"Gleichungen addieren – $y$ fällt weg:","math":"2x = 100"},{"text":"Nach $x$ auflösen:","math":"x = 50"},{"text":"$x$ in Gleichung I einsetzen:","math":"50 + y = 54 \\;\\Rightarrow\\; y = 4"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 50$, $y = 4$', null, null),
  ('lgs-gs-sach-08', '[{"text":"Variablen: $x$ = größere Zahl, $y$ = kleinere Zahl. Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & x + y = 65 \\\\ \\text{II:}\\;\\; & x - y = 51 \\end{aligned}"},{"text":"Gleichungen addieren – $y$ fällt weg:","math":"2x = 116"},{"text":"Nach $x$ auflösen:","math":"x = 58"},{"text":"$x$ in Gleichung I einsetzen:","math":"58 + y = 65 \\;\\Rightarrow\\; y = 7"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 58$, $y = 7$', null, null),
  ('lgs-gs-sach-09', '[{"text":"Variablen: $x$ = Alter der Mutter, $y$ = Alter der Tochter. Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & x + y = 52 \\\\ \\text{II:}\\;\\; & x - y = 24 \\end{aligned}"},{"text":"Gleichungen addieren – $y$ fällt weg:","math":"2x = 76"},{"text":"Nach $x$ auflösen:","math":"x = 38"},{"text":"$x$ in Gleichung I einsetzen:","math":"38 + y = 52 \\;\\Rightarrow\\; y = 14"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 38$, $y = 14$', null, null),
  ('lgs-gs-sach-10', '[{"text":"Variablen: $x$ = Alter der Mutter, $y$ = Alter der Tochter. Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & x + y = 49 \\\\ \\text{II:}\\;\\; & x - y = 31 \\end{aligned}"},{"text":"Gleichungen addieren – $y$ fällt weg:","math":"2x = 80"},{"text":"Nach $x$ auflösen:","math":"x = 40"},{"text":"$x$ in Gleichung I einsetzen:","math":"40 + y = 49 \\;\\Rightarrow\\; y = 9"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 40$, $y = 9$', null, null),
  ('lgs-gs-sach-schwer-01', '[{"text":"Variablen: $x$ = Preis eines Hefts, $y$ = Preis eines Stifts (in €). Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & 3x + 3y = 8{,}1 \\\\ \\text{II:}\\;\\; & 2x + 5y = 9 \\end{aligned}"},{"text":"Gleichungen so multiplizieren, dass vor $y$ gleich große Zahlen stehen (I · 5) (II · 3):","math":"\\begin{aligned} & 15x + 15y = 40{,}5 \\\\ & 6x + 15y = 27 \\end{aligned}"},{"text":"Gleichung II von I abziehen – $y$ fällt weg:","math":"9x = 13{,}5"},{"text":"Nach $x$ auflösen:","math":"x = 1{,}5"},{"text":"$x$ in Gleichung I einsetzen:","math":"4{,}5 + 3y = 8{,}1 \\;\\Rightarrow\\; y = 1{,}2"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 1{,}5$, $y = 1{,}2$', null, null),
  ('lgs-gs-sach-schwer-02', '[{"text":"Variablen: $x$ = Liter Saft, $y$ = Liter Wasser. Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & x + y = 11 \\\\ \\text{II:}\\;\\; & 2{,}5x + 0{,}5y = 15{,}5 \\end{aligned}"},{"text":"Gleichungen so multiplizieren, dass vor $y$ gleich große Zahlen stehen (II · 2):","math":"\\begin{aligned} & x + y = 11 \\\\ & 5x + y = 31 \\end{aligned}"},{"text":"Gleichung II von I abziehen – $y$ fällt weg:","math":"-4x = -20"},{"text":"Nach $x$ auflösen:","math":"x = 5"},{"text":"$x$ in Gleichung I einsetzen:","math":"5 + y = 11 \\;\\Rightarrow\\; y = 6"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 5$, $y = 6$', null, null),
  ('lgs-gs-sach-schwer-03', '[{"text":"Variablen: $x$ = Liter Saft, $y$ = Liter Wasser. Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & x + y = 11 \\\\ \\text{II:}\\;\\; & 1{,}5x + 0{,}5y = 11{,}5 \\end{aligned}"},{"text":"Gleichungen so multiplizieren, dass vor $y$ gleich große Zahlen stehen (II · 2):","math":"\\begin{aligned} & x + y = 11 \\\\ & 3x + y = 23 \\end{aligned}"},{"text":"Gleichung II von I abziehen – $y$ fällt weg:","math":"-2x = -12"},{"text":"Nach $x$ auflösen:","math":"x = 6"},{"text":"$x$ in Gleichung I einsetzen:","math":"6 + y = 11 \\;\\Rightarrow\\; y = 5"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 6$, $y = 5$', null, null),
