  ('lgs-gs-sach-schwer-05', '[{"text":"Variablen: $x$ = Preis eines Hefts, $y$ = Preis eines Stifts (in €). Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & 2x + 4y = 6 \\\\ \\text{II:}\\;\\; & 3x + 4y = 8 \\end{aligned}"},{"text":"Gleichung II von I abziehen – $y$ fällt weg:","math":"-x = -2"},{"text":"Nach $x$ auflösen:","math":"x = 2"},{"text":"$x$ in Gleichung I einsetzen:","math":"4 + 4y = 6 \\;\\Rightarrow\\; y = 0{,}5"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 2$, $y = 0{,}5$', null, null),
  ('lgs-gs-sach-schwer-06', '[{"text":"Variablen: $x$ = Länge, $y$ = Breite (in cm). Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & 2x + 2y = 32 \\\\ \\text{II:}\\;\\; & x - y = 2 \\end{aligned}"},{"text":"Gleichungen so multiplizieren, dass vor $y$ gleich große Zahlen stehen (II · 2):","math":"\\begin{aligned} & 2x + 2y = 32 \\\\ & 2x - 2y = 4 \\end{aligned}"},{"text":"Gleichungen addieren – $y$ fällt weg:","math":"4x = 36"},{"text":"Nach $x$ auflösen:","math":"x = 9"},{"text":"$x$ in Gleichung I einsetzen:","math":"18 + 2y = 32 \\;\\Rightarrow\\; y = 7"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 9$, $y = 7$', null, null),
