  ('lgs-sa-loesen-schwer-07', '[{"text":"Variablen: $x$ = Länge, $y$ = Breite (in cm). Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & 2x + 2y = 44 \\\\ \\text{II:}\\;\\; & x - y = 2 \\end{aligned}"},{"text":"Gleichungen so multiplizieren, dass vor $y$ gleich große Zahlen stehen (II · 2):","math":"\\begin{aligned} & 2x + 2y = 44 \\\\ & 2x - 2y = 4 \\end{aligned}"},{"text":"Gleichungen addieren – $y$ fällt weg:","math":"4x = 48"},{"text":"Nach $x$ auflösen:","math":"x = 12"},{"text":"$x$ in Gleichung I einsetzen:","math":"24 + 2y = 44 \\;\\Rightarrow\\; y = 10"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 12$, $y = 10$', null, null),
  ('lgs-sa-loesen-schwer-08', '[{"text":"Variablen: $x$ = Länge, $y$ = Breite (in cm). Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & 2x + 2y = 24 \\\\ \\text{II:}\\;\\; & x - y = 4 \\end{aligned}"},{"text":"Gleichungen so multiplizieren, dass vor $y$ gleich große Zahlen stehen (II · 2):","math":"\\begin{aligned} & 2x + 2y = 24 \\\\ & 2x - 2y = 8 \\end{aligned}"},{"text":"Gleichungen addieren – $y$ fällt weg:","math":"4x = 32"},{"text":"Nach $x$ auflösen:","math":"x = 8"},{"text":"$x$ in Gleichung I einsetzen:","math":"16 + 2y = 24 \\;\\Rightarrow\\; y = 4"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 8$, $y = 4$', null, null),
  ('lgs-sa-loesen-schwer-09', '[{"text":"Variablen: $x$ = Preis eines Hefts, $y$ = Preis eines Stifts (in €). Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & 2x + 3y = 6 \\\\ \\text{II:}\\;\\; & 3x + 6y = 10{,}5 \\end{aligned}"},{"text":"Gleichungen so multiplizieren, dass vor $y$ gleich große Zahlen stehen (I · 2):","math":"\\begin{aligned} & 4x + 6y = 12 \\\\ & 3x + 6y = 10{,}5 \\end{aligned}"},{"text":"Gleichung II von I abziehen – $y$ fällt weg:","math":"x = 1{,}5"},{"text":"Nach $x$ auflösen:","math":"x = 1{,}5"},{"text":"$x$ in Gleichung I einsetzen:","math":"3 + 3y = 6 \\;\\Rightarrow\\; y = 1"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 1{,}5$, $y = 1$', null, null),
  ('lgs-sa-loesen-schwer-10', '[{"text":"Variablen: $x$ = Liter Saft, $y$ = Liter Wasser. Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & x + y = 13 \\\\ \\text{II:}\\;\\; & 2x + 0{,}5y = 11 \\end{aligned}"},{"text":"Gleichungen so multiplizieren, dass vor $y$ gleich große Zahlen stehen (II · 2):","math":"\\begin{aligned} & x + y = 13 \\\\ & 4x + y = 22 \\end{aligned}"},{"text":"Gleichung II von I abziehen – $y$ fällt weg:","math":"-3x = -9"},{"text":"Nach $x$ auflösen:","math":"x = 3"},{"text":"$x$ in Gleichung I einsetzen:","math":"3 + y = 13 \\;\\Rightarrow\\; y = 10"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 3$, $y = 10$', null, null),
  ('lgs-sa-loesen-schwer-11', '[{"text":"Variablen: $x$ = Länge, $y$ = Breite (in cm). Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & 2x + 2y = 72 \\\\ \\text{II:}\\;\\; & x - y = 8 \\end{aligned}"},{"text":"Gleichungen so multiplizieren, dass vor $y$ gleich große Zahlen stehen (II · 2):","math":"\\begin{aligned} & 2x + 2y = 72 \\\\ & 2x - 2y = 16 \\end{aligned}"},{"text":"Gleichungen addieren – $y$ fällt weg:","math":"4x = 88"},{"text":"Nach $x$ auflösen:","math":"x = 22"},{"text":"$x$ in Gleichung I einsetzen:","math":"44 + 2y = 72 \\;\\Rightarrow\\; y = 14"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 22$, $y = 14$', null, null),
  ('lgs-sa-loesen-schwer-12', '[{"text":"Variablen: $x$ = Anzahl Sitzplatzkarten, $y$ = Anzahl Stehplatzkarten. Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & x + y = 304 \\\\ \\text{II:}\\;\\; & 30x + 22y = 8216 \\end{aligned}"},{"text":"Gleichungen so multiplizieren, dass vor $y$ gleich große Zahlen stehen (I · 22):","math":"\\begin{aligned} & 22x + 22y = 6688 \\\\ & 30x + 22y = 8216 \\end{aligned}"},{"text":"Gleichung II von I abziehen – $y$ fällt weg:","math":"-8x = -1528"},{"text":"Nach $x$ auflösen:","math":"x = 191"},{"text":"$x$ in Gleichung I einsetzen:","math":"191 + y = 304 \\;\\Rightarrow\\; y = 113"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 191$, $y = 113$', null, null),
  ('lgs-sa-loesen-schwer-13', '[{"text":"Variablen: $x$ = Länge, $y$ = Breite (in cm). Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & 2x + 2y = 28 \\\\ \\text{II:}\\;\\; & x - y = 4 \\end{aligned}"},{"text":"Gleichungen so multiplizieren, dass vor $y$ gleich große Zahlen stehen (II · 2):","math":"\\begin{aligned} & 2x + 2y = 28 \\\\ & 2x - 2y = 8 \\end{aligned}"},{"text":"Gleichungen addieren – $y$ fällt weg:","math":"4x = 36"},{"text":"Nach $x$ auflösen:","math":"x = 9"},{"text":"$x$ in Gleichung I einsetzen:","math":"18 + 2y = 28 \\;\\Rightarrow\\; y = 5"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 9$, $y = 5$', null, null),
  ('lgs-sa-loesen-schwer-14', '[{"text":"Variablen: $x$ = Preis eines Hefts, $y$ = Preis eines Stifts (in €). Gleichungssystem:","math":"\\begin{aligned} \\text{I:}\\;\\; & 5x + 3y = 15{,}5 \\\\ \\text{II:}\\;\\; & 3x + 4y = 11{,}5 \\end{aligned}"},{"text":"Gleichungen so multiplizieren, dass vor $y$ gleich große Zahlen stehen (I · 4) (II · 3):","math":"\\begin{aligned} & 20x + 12y = 62 \\\\ & 9x + 12y = 34{,}5 \\end{aligned}"},{"text":"Gleichung II von I abziehen – $y$ fällt weg:","math":"11x = 27{,}5"},{"text":"Nach $x$ auflösen:","math":"x = 2{,}5"},{"text":"$x$ in Gleichung I einsetzen:","math":"12{,}5 + 3y = 15{,}5 \\;\\Rightarrow\\; y = 1"},{"text":"Probe mit Gleichung II bestätigt das Ergebnis."}]'::jsonb, '$x = 2{,}5$, $y = 1$', null, null),
  ('lgs-sa-fc-1', '[{"text":"Für zwei Unbekannte braucht man zwei (voneinander unabhängige) Gleichungen."}]'::jsonb, 'zwei (aus zwei verschiedenen Informationen)', null, null),
  ('pyth-grundlagen-1', '[{"text":"Die beiden Seiten am rechten Winkel heißen Katheten."},{"text":"Die dritte Seite liegt dem rechten Winkel gegenüber – das ist die Hypotenuse."}]'::jsonb, 'Die Seite gegenüber dem rechten Winkel.', null, null),
  ('pyth-grundlagen-2', '[{"text":"Seite $c$ liegt gegenüber von $C$, also gegenüber dem rechten Winkel: $c$ ist die Hypotenuse."},{"text":"$a$ und $b$ sind die Katheten.","math":"a^2 + b^2 = c^2"}]'::jsonb, '$a^2 + b^2 = c^2$', null, null),
