  ('pyth-erkennen-1', '[{"text":"Nur bei $30^\\circ$, $60^\\circ$, $90^\\circ$ gibt es einen rechten Winkel."}]'::jsonb, '$30^\circ$, $60^\circ$, $90^\circ$', null, null),
  ('pyth-erkennen-2', '[{"text":"Winkelsumme nutzen:","math":"\\gamma = 180^\\circ - \\alpha - \\beta"},{"text":"Einsetzen:","math":"\\gamma = 180^\\circ - 27^\\circ - 63^\\circ = 90^\\circ"}]'::jsonb, '$\gamma = 90^\circ$ – das Dreieck ist rechtwinklig.', null, null),
  ('pyth-erkennen-3', '[{"text":"Rechter Winkel bei $X$ ⇒ die Katheten sind $\\overline{XY}$ und $\\overline{XZ}$."},{"text":"Die verbleibende Seite ist die Hypotenuse."}]'::jsonb, '$\overline{YZ}$', null, null),
  ('pyth-erkennen-4', '[{"text":"Rechten Winkel bei $C$ zeichnen und mit einem Viertelkreis mit Punkt markieren."},{"text":"Die Seiten $a = \\overline{BC}$ und $b = \\overline{AC}$ sind die Katheten."},{"text":"Die Seite $c = \\overline{AB}$ liegt gegenüber dem rechten Winkel."}]'::jsonb, 'Hypotenuse: $c$', null, null),
  ('pyth-er-winkelsumme-01', '[{"text":"Die drei Winkel eines Dreiecks ergeben zusammen immer $180^\\circ$:","math":"\\alpha + \\beta + \\gamma = 180^\\circ"},{"text":"Zwei Winkel kennen wir schon: $\\alpha = 75^\\circ$ und $\\beta = 67^\\circ$. Zusammen sind das:","math":"75^\\circ + 67^\\circ = 142^\\circ"},{"text":"Bis $180^\\circ$ fehlen noch:","math":"180^\\circ - 142^\\circ = 38^\\circ"},{"text":"Dieser fehlende Winkel ist $\\gamma$. Also ist $\\gamma = 38^\\circ$."}]'::jsonb, '$\gamma = 38^\circ$', null, null),
  ('pyth-er-winkelsumme-02', '[{"text":"Die drei Winkel eines Dreiecks ergeben zusammen immer $180^\\circ$:","math":"\\alpha + \\beta + \\gamma = 180^\\circ"},{"text":"Zwei Winkel kennen wir schon: $\\alpha = 26^\\circ$ und $\\beta = 119^\\circ$. Zusammen sind das:","math":"26^\\circ + 119^\\circ = 145^\\circ"},{"text":"Bis $180^\\circ$ fehlen noch:","math":"180^\\circ - 145^\\circ = 35^\\circ"},{"text":"Dieser fehlende Winkel ist $\\gamma$. Also ist $\\gamma = 35^\\circ$."}]'::jsonb, '$\gamma = 35^\circ$', null, null),
  ('pyth-er-winkelsumme-03', '[{"text":"Die drei Winkel eines Dreiecks ergeben zusammen immer $180^\\circ$:","math":"\\alpha + \\beta + \\gamma = 180^\\circ"},{"text":"Zwei Winkel kennen wir schon: $\\alpha = 48^\\circ$ und $\\beta = 97^\\circ$. Zusammen sind das:","math":"48^\\circ + 97^\\circ = 145^\\circ"},{"text":"Bis $180^\\circ$ fehlen noch:","math":"180^\\circ - 145^\\circ = 35^\\circ"},{"text":"Dieser fehlende Winkel ist $\\gamma$. Also ist $\\gamma = 35^\\circ$."}]'::jsonb, '$\gamma = 35^\circ$', null, null),
  ('pyth-er-winkelsumme-04', '[{"text":"Die drei Winkel eines Dreiecks ergeben zusammen immer $180^\\circ$:","math":"\\alpha + \\beta + \\gamma = 180^\\circ"},{"text":"Zwei Winkel kennen wir schon: $\\alpha = 67^\\circ$ und $\\beta = 29^\\circ$. Zusammen sind das:","math":"67^\\circ + 29^\\circ = 96^\\circ"},{"text":"Bis $180^\\circ$ fehlen noch:","math":"180^\\circ - 96^\\circ = 84^\\circ"},{"text":"Dieser fehlende Winkel ist $\\gamma$. Also ist $\\gamma = 84^\\circ$."}]'::jsonb, '$\gamma = 84^\circ$', null, null),
  ('pyth-er-winkelsumme-05', '[{"text":"Die drei Winkel eines Dreiecks ergeben zusammen immer $180^\\circ$:","math":"\\alpha + \\beta + \\gamma = 180^\\circ"},{"text":"Zwei Winkel kennen wir schon: $\\alpha = 67^\\circ$ und $\\beta = 25^\\circ$. Zusammen sind das:","math":"67^\\circ + 25^\\circ = 92^\\circ"},{"text":"Bis $180^\\circ$ fehlen noch:","math":"180^\\circ - 92^\\circ = 88^\\circ"},{"text":"Dieser fehlende Winkel ist $\\gamma$. Also ist $\\gamma = 88^\\circ$."}]'::jsonb, '$\gamma = 88^\circ$', null, null),
