insert into public.solutions (exercise_id, steps, final_answer, alternative, detailed) values
  ('pyth-ka-leiter-01', '[{"text":"Kathete berechnen:","math":"h = \\sqrt{4^2 - 1^2} = \\sqrt{15} \\approx 3{,}87"}]'::jsonb, '$\approx 3{,}87$ m', null, '[{"title":"Wo steckt das rechtwinklige Dreieck?","text":"Wand und Boden stehen senkrecht aufeinander. Die Leiter ist die schräge Seite und damit die Hypotenuse. Der Abstand des Fußes zur Wand und die gesuchte Höhe an der Wand sind die Katheten."},{"title":"Was ist gegeben, was ist gesucht?","text":"Gegeben sind die Hypotenuse $c = 4$ m (die längste Seite, gegenüber dem rechten Winkel) und eine Kathete $a = 1$ m. Gesucht ist die zweite Kathete $b$ (die Höhe an der Wand).","figure":{"kind":"right-triangle","alt":"Rechtwinkliges Dreieck mit der Hypotenuse c = 4 m und der Kathete a = 1 m; die Kathete b ist gesucht.","labels":{"c":"c = 4 m","a":"a = 1 m","b":"b = ?"},"highlight":"b","ratio":[1.5491933384829668,3.872983346207417]}},{"title":"Welche Formel passt?","text":"Ausgangspunkt ist wieder der Satz des Pythagoras. Weil diesmal eine Kathete fehlt, stellst du ihn nach $b^2$ um: Ziehe auf beiden Seiten $a^2$ ab.","math":"a^2 + b^2 = c^2 \\;\\Rightarrow\\; b^2 = c^2 - a^2"},{"title":"Werte einsetzen","text":"Achte darauf, dass die Hypotenuse vorne steht – sonst wird das Ergebnis negativ.","math":"b^2 = 4^2 - 1^2"},{"title":"Quadrate ausrechnen","text":"Zuerst quadrieren, dann subtrahieren.","math":"b^2 = 16 - 1 = 15"},{"title":"Wurzel ziehen","text":"Gesucht ist $b$, nicht $b^2$: Wurzel ziehen, nur die positive Lösung zählt. Die Wurzel geht nicht glatt auf – runde auf 2 Nachkommastellen und schreibe „≈“.","math":"b = \\sqrt{15} \\approx 3{,}87"},{"title":"Ergebnis prüfen","text":"Eine Kathete ist immer kürzer als die Hypotenuse: $3{,}87 < 4$ stimmt. Probe: $3{,}87^2 + 1^2 \\approx 16$. Ergebnis: $b \\approx 3{,}87$ m."}]'::jsonb),
  ('pyth-ka-leiter-02', '[{"text":"Kathete berechnen:","math":"h = \\sqrt{3^2 - 2^2} = \\sqrt{5} \\approx 2{,}24"}]'::jsonb, '$\approx 2{,}24$ m', null, '[{"title":"Wo steckt das rechtwinklige Dreieck?","text":"Wand und Boden stehen senkrecht aufeinander. Die Leiter ist die schräge Seite und damit die Hypotenuse. Der Abstand des Fußes zur Wand und die gesuchte Höhe an der Wand sind die Katheten."},{"title":"Was ist gegeben, was ist gesucht?","text":"Gegeben sind die Hypotenuse $c = 3$ m (die längste Seite, gegenüber dem rechten Winkel) und eine Kathete $a = 2$ m. Gesucht ist die zweite Kathete $b$ (die Höhe an der Wand).","figure":{"kind":"right-triangle","alt":"Rechtwinkliges Dreieck mit der Hypotenuse c = 3 m und der Kathete a = 2 m; die Kathete b ist gesucht.","labels":{"c":"c = 3 m","a":"a = 2 m","b":"b = ?"},"highlight":"b","ratio":[2,2.23606797749979]}},{"title":"Welche Formel passt?","text":"Ausgangspunkt ist wieder der Satz des Pythagoras. Weil diesmal eine Kathete fehlt, stellst du ihn nach $b^2$ um: Ziehe auf beiden Seiten $a^2$ ab.","math":"a^2 + b^2 = c^2 \\;\\Rightarrow\\; b^2 = c^2 - a^2"},{"title":"Werte einsetzen","text":"Achte darauf, dass die Hypotenuse vorne steht – sonst wird das Ergebnis negativ.","math":"b^2 = 3^2 - 2^2"},{"title":"Quadrate ausrechnen","text":"Zuerst quadrieren, dann subtrahieren.","math":"b^2 = 9 - 4 = 5"},{"title":"Wurzel ziehen","text":"Gesucht ist $b$, nicht $b^2$: Wurzel ziehen, nur die positive Lösung zählt. Die Wurzel geht nicht glatt auf – runde auf 2 Nachkommastellen und schreibe „≈“.","math":"b = \\sqrt{5} \\approx 2{,}24"},{"title":"Ergebnis prüfen","text":"Eine Kathete ist immer kürzer als die Hypotenuse: $2{,}24 < 3$ stimmt. Probe: $2{,}24^2 + 2^2 \\approx 9$. Ergebnis: $b \\approx 2{,}24$ m."}]'::jsonb),
