  ('qf-ns-hoehe-05', '[{"text":"Gleichung aufstellen und umformen:","math":"-5t^2 + 25t - 20 = 0 \\;\\Rightarrow\\; t^2 - 5t + 4 = 0"},{"text":"pq-Formel:","math":"t_{1,2} = 2{,}5 \\pm \\sqrt{6{,}25 - 4}"},{"text":"Wurzel berechnen:","math":"t_{1,2} = 2{,}5 \\pm \\sqrt{2{,}25} = 2{,}5 \\pm 1{,}5"},{"text":"Lösungen:","math":"t_1 = 1,\\; t_2 = 4"}]'::jsonb, 'nach $1$ s und nach $4$ s', null, null),
  ('qf-ns-hoehe-06', '[{"text":"Gleichung aufstellen und umformen:","math":"-5t^2 + 45t - 90 = 0 \\;\\Rightarrow\\; t^2 - 9t + 18 = 0"},{"text":"pq-Formel:","math":"t_{1,2} = 4{,}5 \\pm \\sqrt{20{,}25 - 18}"},{"text":"Wurzel berechnen:","math":"t_{1,2} = 4{,}5 \\pm \\sqrt{2{,}25} = 4{,}5 \\pm 1{,}5"},{"text":"Lösungen:","math":"t_1 = 3,\\; t_2 = 6"}]'::jsonb, 'nach $3$ s und nach $6$ s', null, null),
  ('qf-ns-hoehe-07', '[{"text":"Gleichung aufstellen und umformen:","math":"-5t^2 + 30t - 25 = 0 \\;\\Rightarrow\\; t^2 - 6t + 5 = 0"},{"text":"pq-Formel:","math":"t_{1,2} = 3 \\pm \\sqrt{9 - 5}"},{"text":"Wurzel berechnen:","math":"t_{1,2} = 3 \\pm \\sqrt{4} = 3 \\pm 2"},{"text":"Lösungen:","math":"t_1 = 1,\\; t_2 = 5"}]'::jsonb, 'nach $1$ s und nach $5$ s', null, null),
  ('qf-ns-hoehe-08', '[{"text":"Gleichung aufstellen und umformen:","math":"-5t^2 + 20t - 15 = 0 \\;\\Rightarrow\\; t^2 - 4t + 3 = 0"},{"text":"pq-Formel:","math":"t_{1,2} = 2 \\pm \\sqrt{4 - 3}"},{"text":"Wurzel berechnen:","math":"t_{1,2} = 2 \\pm \\sqrt{1} = 2 \\pm 1"},{"text":"Lösungen:","math":"t_1 = 1,\\; t_2 = 3"}]'::jsonb, 'nach $1$ s und nach $3$ s', null, null),
